window.__DAILY_CHUNKS__[2] = [{"week":10,"level":"A1","theme":"主有形容词、指示形容词与家庭","days":[{"day":1,"theme":"词汇 · 家庭与关系","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：家庭与关系","body":"家庭与关系（La famille et les relations）是这一周要反复见面的主题域。打开 vocab.html#t2，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"mon père\">mon père</span>（我的父亲）、<span class=\"fr\" data-fr=\"ma mère\">ma mère</span>（我的母亲）、<span class=\"fr\" data-fr=\"mes parents\">mes parents</span>（我的父母）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t2","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5035","level":"A1","skill":"vocab","prompt":"« mes grands-parents » 的意思是？","options":["我的祖父母","我的父母","我的兄弟姐妹"],"answer":"我的祖父母","explain":"grands-parents 是祖父母；parents 是父母；frères et sœurs 是兄弟姐妹。","source":"词汇 · 家庭"},{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"vocab","title":"搭配与辨析：mon frère / ma sœur","body":"<span class=\"fr\" data-fr=\"mon frère\">mon frère</span>（我的兄弟）与 <span class=\"fr\" data-fr=\"ma sœur\">ma sœur</span>（我的姐妹）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t2","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5036","level":"A1","skill":"vocab","prompt":"「我的姐妹」用法语说是？","options":["ma sœur","mon sœur","ma soeur"],"answer":"ma sœur","explain":"sœur 是阴性名词，用 ma；œ 是连体字母，不能拆写成 oe。","source":"词汇 · 家庭"},{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"listen","title":"听音辨词：家庭与关系","body":"打开 对话页的 d10 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"mes grands-parents\">mes grands-parents</span>（我的祖父母）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d10","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Mon père et ma mère habitent à Nice.\">Mon père et ma mère habitent à Nice.</span>（我的父亲和母亲住在尼斯。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：家庭与关系 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"mon père\">mon père</span> <span class=\"fr\" data-fr=\"ma mère\">ma mère</span> <span class=\"fr\" data-fr=\"mes parents\">mes parents</span> <span class=\"fr\" data-fr=\"mon frère\">mon frère</span> <span class=\"fr\" data-fr=\"ma sœur\">ma sœur</span> <span class=\"fr\" data-fr=\"mes grands-parents\">mes grands-parents</span>。说不出来的词立刻回到 vocab.html#t2 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t2","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]}]},{"day":2,"theme":"语法 · 主有形容词","type":"grammar","steps":[{"type":"grammar","title":"语法点：主有形容词","body":"【主有形容词】主有形容词 mon / ma / mes、ton / ta / tes、son / sa / ses、notre / nos、votre / vos、leur / leurs 的形式由被拥有名词的性和数决定，与所有者的性别无关。指示形容词 ce / cet / cette / ces 里，cet 只用于元音或哑音 h 开头的阳性单数名词前。 例句：<span class=\"fr\" data-fr=\"Mon père et ma mère habitent à Nice.\">Mon père et ma mère habitent à Nice.</span>（我的父亲和母亲住在尼斯。）；<span class=\"fr\" data-fr=\"Cet ami est mon voisin.\">Cet ami est mon voisin.</span>（这位朋友是我的邻居。）。对照 grammar-a1a2.html#adj-poss 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#adj-poss","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5035","level":"A1","skill":"grammar","prompt":"« ___ mère » 中应填？","options":["ma","mon","mes"],"answer":"ma","explain":"mère 是阴性单数名词，用 ma；mon 只给阳性单数。","source":"语法 · 主有形容词"},{"ref":"bank:grammar:A1:主有形容词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#adj-poss 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Mon père et ma mère habitent à Nice.\">Mon père et ma mère habitent à Nice.</span>（我的父亲和母亲住在尼斯。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#adj-poss","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5036","level":"A1","skill":"grammar","prompt":"« ___ ami »（阳性单数、元音开头）应填？","options":["cet","ce","cette"],"answer":"cet","explain":"ami 以元音开头且为阳性单数，指示形容词用 cet；ce 只用于辅音开头。","source":"语法 · 指示形容词"},{"ref":"bank:grammar:A1:主有形容词"}]},{"type":"read","title":"在短文里找主有形容词","body":"在 grammar-a1a2.html#adj-poss 的例句和章末小测里挑 5 句，圈出所有属于「主有形容词」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#adj-poss","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Mon père et ma mère habitent à Nice.\">Mon père et ma mère habitent à Nice.</span>（我的父亲和母亲住在尼斯。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，主有形容词 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：指示形容词","body":"今天再回 grammar-a1a2.html#adj-dem 看一遍 指示形容词，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#adj-dem","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:主有形容词"}]}]},{"day":3,"theme":"精听 · 对话页的 d10 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d10 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d10","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5021","level":"A1","skill":"listening","prompt":"听到 /mɔ̃ pɛʁ/ 对应的写法是？","options":["mon père","ma mère","mes pères"],"answer":"mon père","explain":"père 是阳性单数，用 mon；ma mère 是母亲，元音不同。","source":"语法 · 主有形容词"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段家庭介绍，画出家谱图并标出每个人与说话人的关系。","src":"dialogue.html#d10","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"mon père\">mon père</span>（我的父亲）、<span class=\"fr\" data-fr=\"ma mère\">ma mère</span>（我的母亲）、<span class=\"fr\" data-fr=\"mes parents\">mes parents</span>（我的父母）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t2","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「主有形容词 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d10","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 主有形容词、指示形容词与家庭","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：介绍家庭 3 分钟，包含成员、年龄、职业、住哪，主有形容词不能出错。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5012","level":"A1","skill":"speaking","prompt":"「这是我的父母」正确说法是？","options":["Ce sont mes parents.","C'est mes parents.","Ce sont mon parents."],"answer":"Ce sont mes parents.","explain":"复数用 Ce sont；parents 是复数，主有形容词用 mes。","source":"语法 · 主有形容词"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d10 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、主有形容词 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d10","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"mon frère\">mon frère</span>（我的兄弟）、<span class=\"fr\" data-fr=\"ma sœur\">ma sœur</span>（我的姐妹）、<span class=\"fr\" data-fr=\"mes grands-parents\">mes grands-parents</span>（我的祖父母）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t2 再看一遍例句。","src":"vocab.html#t2","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 主有形容词、指示形容词与家庭","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页限定词章节，重点记「主有形容词跟名词性别走，不跟所有者走」。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5019","level":"A1","skill":"reading","prompt":"« leur » 与 « leurs » 的区别在于？","options":["后面名词是单数还是复数","所有者的性别","所有者的数量"],"answer":"后面名词是单数还是复数","explain":"leur / leurs 由被拥有名词的数决定；所有者是单数还是复数并不影响形式。","source":"语法 · 主有形容词"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"mon père\">mon père</span>（我的父亲）、<span class=\"fr\" data-fr=\"ma mère\">ma mère</span>（我的母亲）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t2","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#adj-poss，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#adj-poss","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:主有形容词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「主有形容词」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 主有形容词、指示形容词与家庭","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 12 句家庭介绍，每句含一个主有形容词或指示形容词。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5010","level":"A1","skill":"writing","prompt":"「这位女士是我的老师」正确写法是？","options":["Cette femme est mon professeur.","Ce femme est mon professeur.","Cette femme est ma professeur."],"answer":"Cette femme est mon professeur.","explain":"femme 是阴性单数用 cette；professeur 作名词时按阳性处理，用 mon。","source":"语法 · 指示形容词"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#adj-poss，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#adj-poss","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:主有形容词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「主有形容词」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"mon père\">mon père</span>（我的父亲）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 主有形容词、指示形容词与家庭","type":"review","steps":[{"type":"review","title":"本周回顾：主有形容词、指示形容词与家庭","body":"这一周围绕「主有形容词、指示形容词与家庭」展开：语法主线是 主有形容词，词汇主线是 家庭与关系。先用 3 句话口头复述本周学了什么，再打开日历页第 10 周清单逐条核对里程碑。","src":"calendar.html#wk-10","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"review","title":"语法复盘：主有形容词","body":"从 grammar-a1a2.html#adj-poss 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#adj-poss","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:主有形容词"}]},{"type":"review","title":"词汇自测：家庭与关系","body":"遮住中文看 vocab.html#t2 的 6 个核心词：<span class=\"fr\" data-fr=\"mon père\">mon père</span> <span class=\"fr\" data-fr=\"ma mère\">ma mère</span> <span class=\"fr\" data-fr=\"mes parents\">mes parents</span> <span class=\"fr\" data-fr=\"mon frère\">mon frère</span> <span class=\"fr\" data-fr=\"ma sœur\">ma sœur</span> <span class=\"fr\" data-fr=\"mes grands-parents\">mes grands-parents</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t2","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5037","level":"A1","skill":"vocab","prompt":"« mes parents » 的意思是？","options":["我的父母","我的亲戚","我的孩子"],"answer":"我的父母","explain":"parents 指父母；parents éloignés 才是远亲；enfants 是孩子。","source":"词汇 · 家庭"},{"id":"q-vocab-a1-5038","level":"A1","skill":"vocab","prompt":"「我的兄弟」用法语说是？","options":["mon frère","ma frère","mes frère"],"answer":"mon frère","explain":"frère 是阳性单数，用 mon。","source":"词汇 · 家庭"},{"ref":"bank:vocab:A1:家庭与关系"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d10","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5022","level":"A1","skill":"listening","prompt":"« ces amis » 的正确读法是？","options":["/sezami/","/sɛami/","/sɛsami/"],"answer":"/sezami/","explain":"ces 与元音开头的 amis 之间必须联诵，s 读 /z/。","source":"语音 · 联诵"},{"id":"q-read-a1-5020","level":"A1","skill":"reading","prompt":"« notre » 与 « nos » 分别用于？","options":["单数名词与复数名词","阳性与阴性","单数所有者与复数所有者"],"answer":"单数名词与复数名词","explain":"notre 后接单数名词，nos 后接复数名词，与所有者人数无关。","source":"语法 · 主有形容词"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 主有形容词 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#adj-poss 再核对一次。","src":"grammar-a1a2.html#adj-dem","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5037","level":"A1","skill":"grammar","prompt":"« ___ enfance »（阴性单数名词）应填？","options":["mon","ma","mes"],"answer":"mon","explain":"enfance 虽为阴性，但以元音开头，为发音顺畅用 mon enfance。","source":"语法 · 主有形容词"},{"id":"q-gram-a1-5038","level":"A1","skill":"grammar","prompt":"« ___ livres » 中应填？","options":["ces","ce","cet"],"answer":"ces","explain":"livres 是复数名词，指示形容词用 ces。","source":"语法 · 指示形容词"},{"ref":"bank:grammar:A1:主有形容词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":11,"level":"A1","theme":"最近将来与最近过去、计划与刚发生","days":[{"day":1,"theme":"词汇 · 城市与交通","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：城市与交通","body":"本周词汇主战场是城市与交通（La ville et les transports）。先到 vocab.html#t9 把词表扫一遍，把 <span class=\"fr\" data-fr=\"aller\">aller</span>（去）、<span class=\"fr\" data-fr=\"partir\">partir</span>（出发）、<span class=\"fr\" data-fr=\"arriver\">arriver</span>（到达）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t9","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5039","level":"A1","skill":"vocab","prompt":"« un rendez-vous » 的意思是？","options":["约会；门诊","假期","车票"],"answer":"约会；门诊","explain":"rendez-vous 指约定的见面或门诊预约；vacances 是假期；billet 是票。","source":"词汇 · 日常事务"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"vocab","title":"搭配与辨析：bientôt / tout de suite","body":"把 <span class=\"fr\" data-fr=\"bientôt\">bientôt</span>（不久）和 <span class=\"fr\" data-fr=\"tout de suite\">tout de suite</span>（马上）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t9","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5040","level":"A1","skill":"vocab","prompt":"« bientôt » 的意思是？","options":["不久","马上","昨天"],"answer":"不久","explain":"bientôt 是不久、很快；tout de suite 是马上；hier 是昨天。","source":"词汇 · 时间"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"listen","title":"听音辨词：城市与交通","body":"打开 对话页的 d05、d18 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"le rendez-vous\">le rendez-vous</span>（约会；门诊）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d05","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je vais prendre le train demain matin.\">Je vais prendre le train demain matin.</span>（我明天早上要坐火车。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：城市与交通 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"aller\">aller</span> <span class=\"fr\" data-fr=\"partir\">partir</span> <span class=\"fr\" data-fr=\"arriver\">arriver</span> <span class=\"fr\" data-fr=\"bientôt\">bientôt</span> <span class=\"fr\" data-fr=\"tout de suite\">tout de suite</span> <span class=\"fr\" data-fr=\"le rendez-vous\">le rendez-vous</span>。说不出来的词立刻回到 vocab.html#t9 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t9","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]}]},{"day":2,"theme":"语法 · 最近将来时","type":"grammar","steps":[{"type":"grammar","title":"语法点：最近将来时","body":"【最近将来时】aller + 不定式表示最近将来（Je vais partir），venir de + 不定式表示刚刚发生（Je viens de partir），être en train de + 不定式表示正在进行（Je suis en train de travailler）。三种结构只变助动词，实义动词一律用不定式。 例句：<span class=\"fr\" data-fr=\"Je vais prendre le train demain matin.\">Je vais prendre le train demain matin.</span>（我明天早上要坐火车。）；<span class=\"fr\" data-fr=\"Elle vient de téléphoner.\">Elle vient de téléphoner.</span>（她刚打完电话。）。对照 grammar-a1a2.html#futur-proche 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#futur-proche","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5039","level":"A1","skill":"grammar","prompt":"Je ___ partir dans dix minutes.（aller）","options":["vais","va","allons"],"answer":"vais","explain":"最近将来是 aller 的变位加不定式，je 对应 vais。","source":"语法 · 最近将来"},{"ref":"bank:grammar:A1:最近将来"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 最近将来时 的规则和两个例句，再打开 grammar-a1a2.html#futur-proche 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#futur-proche","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5040","level":"A1","skill":"grammar","prompt":"「她刚打完电话」应说？","options":["Elle vient de téléphoner.","Elle vient téléphoner.","Elle va de téléphoner."],"answer":"Elle vient de téléphoner.","explain":"最近过去是 venir de + 不定式，de 不能省略。","source":"语法 · 最近过去"},{"ref":"bank:grammar:A1:最近将来"}]},{"type":"read","title":"在短文里找最近将来时","body":"在 grammar-a1a2.html#futur-proche 的例句和章末小测里挑 5 句，圈出所有属于「最近将来时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#futur-proche","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je vais prendre le train demain matin.\">Je vais prendre le train demain matin.</span>（我明天早上要坐火车。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，最近将来时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：最近过去时","body":"今天再回 grammar-a1a2.html#passe-recent 看一遍 最近过去时，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#passe-recent","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:最近将来"}]}]},{"day":3,"theme":"精听 · 对话页的 d05、d18 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d05、d18 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d05","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5023","level":"A1","skill":"listening","prompt":"听到 /vjɛ̃ də paʁtiʁ/ 表示？","options":["刚刚出发","将要出发","正在出发"],"answer":"刚刚出发","explain":"venir de + 不定式表示刚刚发生，与 aller + 不定式（将要）相对。","source":"语法 · 最近过去"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听日程安排对话，记录 5 个「将要」与 5 个「刚刚」。","src":"dialogue.html#d05","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"aller\">aller</span>（去）、<span class=\"fr\" data-fr=\"partir\">partir</span>（出发）、<span class=\"fr\" data-fr=\"arriver\">arriver</span>（到达）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t9","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「最近将来时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d05","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 最近将来与最近过去、计划与刚发生","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：说这份周末计划（6 句将来）和今天已经做的事（6 句刚过去）。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5013","level":"A1","skill":"speaking","prompt":"「我们正在吃饭」应说？","options":["Nous sommes en train de manger.","Nous allons manger.","Nous venons de manger."],"answer":"Nous sommes en train de manger.","explain":"être en train de + 不定式表示正在做；aller 表将来，venir de 表刚过去。","source":"语法 · 进行表达"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d05、d18 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、最近将来时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d05","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"bientôt\">bientôt</span>（不久）、<span class=\"fr\" data-fr=\"tout de suite\">tout de suite</span>（马上）、<span class=\"fr\" data-fr=\"le rendez-vous\">le rendez-vous</span>（约会；门诊）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t9 再看一遍例句。","src":"vocab.html#t9","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 最近将来与最近过去、计划与刚发生","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页相关时态小节的对比表，把三种结构抄成三行公式。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5021","level":"A1","skill":"reading","prompt":"« Je vais aller… » 中第二个 aller 的形式是？","options":["不定式","过去分词","虚拟式"],"answer":"不定式","explain":"最近将来里 aller 后面的实义动词一律用不定式。","source":"语法 · 最近将来"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「最近将来时」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"aller\">aller</span>（去）、<span class=\"fr\" data-fr=\"partir\">partir</span>（出发）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t9","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#futur-proche，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#futur-proche","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:最近将来"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「最近将来时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 最近将来与最近过去、计划与刚发生","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写一段「下周末计划」（80 词），至少 6 句用最近将来。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5011","level":"A1","skill":"writing","prompt":"「我明天出发」正确写法是？","options":["Je vais partir demain.","Je vais partirai demain.","Je vais partir de demain."],"answer":"Je vais partir demain.","explain":"aller 后接不定式，不能再用变位形式 partirai；demain 前不加介词。","source":"语法 · 最近将来"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#futur-proche，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#futur-proche","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:最近将来"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「最近将来时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"aller\">aller</span>（去）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 最近将来与最近过去、计划与刚发生","type":"review","steps":[{"type":"review","title":"本周回顾：最近将来与最近过去、计划与刚发生","body":"这一周围绕「最近将来与最近过去、计划与刚发生」展开：语法主线是 最近将来时，词汇主线是 城市与交通。先用 3 句话口头复述本周学了什么，再打开日历页第 11 周清单逐条核对里程碑。","src":"calendar.html#wk-11","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"review","title":"语法复盘：最近将来时","body":"从 grammar-a1a2.html#futur-proche 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#futur-proche","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:最近将来"}]},{"type":"review","title":"词汇自测：城市与交通","body":"遮住中文看 vocab.html#t9 的 6 个核心词：<span class=\"fr\" data-fr=\"aller\">aller</span> <span class=\"fr\" data-fr=\"partir\">partir</span> <span class=\"fr\" data-fr=\"arriver\">arriver</span> <span class=\"fr\" data-fr=\"bientôt\">bientôt</span> <span class=\"fr\" data-fr=\"tout de suite\">tout de suite</span> <span class=\"fr\" data-fr=\"le rendez-vous\">le rendez-vous</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t9","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5041","level":"A1","skill":"vocab","prompt":"« tout de suite » 的意思是？","options":["马上","不久","终于"],"answer":"马上","explain":"tout de suite 是立刻、马上；bientôt 是不久；enfin 是终于。","source":"词汇 · 时间"},{"id":"q-vocab-a1-5042","level":"A1","skill":"vocab","prompt":"「出发」用法语说是？","options":["partir","arriver","rester"],"answer":"partir","explain":"partir 是出发、离开；arriver 是到达；rester 是留下。","source":"词汇 · 出行"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d05","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5024","level":"A1","skill":"listening","prompt":"听到 /il vjɛ̃ daʁive/ 表示？","options":["他刚到","他要去","他正在到"],"answer":"他刚到","explain":"venir de + 不定式表刚过去，arriver 表示到达。","source":"语法 · 最近过去"},{"id":"q-read-a1-5022","level":"A1","skill":"reading","prompt":"三种结构中，哪一个表示正在进行？","options":["être en train de + 不定式","aller + 不定式","venir de + 不定式"],"answer":"être en train de + 不定式","explain":"être en train de 表示正在进行；aller 表将来，venir de 表刚过去。","source":"语法 · 进行表达"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 最近将来时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#futur-proche 再核对一次。","src":"grammar-a1a2.html#passe-recent","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5041","level":"A1","skill":"grammar","prompt":"« Nous ___ visiter le musée samedi. »（aller）","options":["allons","vont","allez"],"answer":"allons","explain":"nous 对应 allons；allez 给 vous，vont 给 ils / elles。","source":"语法 · 最近将来"},{"id":"q-gram-a1-5042","level":"A1","skill":"grammar","prompt":"下列哪句表示「刚刚」？","options":["Je viens de finir.","Je vais finir.","Je suis en train de finir."],"answer":"Je viens de finir.","explain":"venir de + 不定式表刚刚完成；aller 表将来；être en train de 表正在。","source":"语法 · 最近过去"},{"ref":"bank:grammar:A1:最近将来"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":12,"level":"A1","theme":"礼貌表达、日常请求与正式书信格式","days":[{"day":1,"theme":"词汇 · 高频动词与万能表达","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：高频动词与万能表达","body":"高频动词与万能表达（Les verbes fréquents et les expressions utiles）是这一周要反复见面的主题域。打开 vocab.html#t25，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span>（请）、<span class=\"fr\" data-fr=\"excusez-moi\">excusez-moi</span>（请原谅）、<span class=\"fr\" data-fr=\"je voudrais\">je voudrais</span>（我想要）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t25","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5043","level":"A1","skill":"vocab","prompt":"« un renseignement » 的意思是？","options":["信息；咨询","发票","预约"],"answer":"信息；咨询","explain":"renseignement 指咨询得到的信息；facture 是发票；rendez-vous 是预约。","source":"词汇 · 办事用语"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"vocab","title":"搭配与辨析：une demande / un renseignement","body":"<span class=\"fr\" data-fr=\"une demande\">une demande</span>（请求）与 <span class=\"fr\" data-fr=\"un renseignement\">un renseignement</span>（信息；咨询）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t25","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5044","level":"A1","skill":"vocab","prompt":"法语正式信函常用落款是？","options":["Cordialement","Au revoir","Salut"],"answer":"Cordialement","explain":"Cordialement 是正式信函常用落款；Au revoir 与 Salut 都太口语化。","source":"词汇 · 书信格式"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"listen","title":"听音辨词：高频动词与万能表达","body":"打开 对话页的 d08、d12、d09 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"cordialement\">cordialement</span>（此致（落款））这样的词如果没听出来，单独标出来。","src":"dialogue.html#d08","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Pourriez-vous m'envoyer les informations ?\">Pourriez-vous m'envoyer les informations ?</span>（您能把信息发给我吗？）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：高频动词与万能表达 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span> <span class=\"fr\" data-fr=\"excusez-moi\">excusez-moi</span> <span class=\"fr\" data-fr=\"je voudrais\">je voudrais</span> <span class=\"fr\" data-fr=\"une demande\">une demande</span> <span class=\"fr\" data-fr=\"un renseignement\">un renseignement</span> <span class=\"fr\" data-fr=\"cordialement\">cordialement</span>。说不出来的词立刻回到 vocab.html#t25 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t25","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]}]},{"day":2,"theme":"语法 · 命令式","type":"grammar","steps":[{"type":"grammar","title":"语法点：命令式","body":"【命令式】礼貌请求常用条件式：Je voudrais…、Pourriez-vous…，比直陈式委婉。正式信函的格式是开头写 Madame, Monsieur,，结尾用 Cordialement 或 Je vous prie d'agréer mes salutations respectueuses，全文统一用 vous，不能中途换成 tu。 例句：<span class=\"fr\" data-fr=\"Pourriez-vous m'envoyer les informations ?\">Pourriez-vous m'envoyer les informations ?</span>（您能把信息发给我吗？）；<span class=\"fr\" data-fr=\"Je vous prie d'agréer mes salutations respectueuses.\">Je vous prie d'agréer mes salutations respectueuses.</span>（顺致敬意。）。对照 grammar-a1a2.html#imperatif 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#imperatif","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5043","level":"A1","skill":"grammar","prompt":"礼貌地说「我想要一个房间」，应说？","options":["Je voudrais une chambre.","Je veux une chambre.","Je voudrai une chambre."],"answer":"Je voudrais une chambre.","explain":"Je voudrais 是条件式，比直陈的 Je veux 礼貌；voudrai 是简单将来时，语气不对。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:grammar:A1:命令式"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#imperatif 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Pourriez-vous m'envoyer les informations ?\">Pourriez-vous m'envoyer les informations ?</span>（您能把信息发给我吗？）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#imperatif","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5044","level":"A1","skill":"grammar","prompt":"« ___ -vous m'aider ? »（礼貌请求）","options":["Pourriez","Pouvez","Pourrez"],"answer":"Pourriez","explain":"条件式 Pourriez-vous 是最礼貌的请求形式；Pourrez 是简单将来时，语气生硬。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:grammar:A1:命令式"}]},{"type":"read","title":"在短文里找命令式","body":"在 grammar-a1a2.html#imperatif 的例句和章末小测里挑 5 句，圈出所有属于「命令式」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#imperatif","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Pourriez-vous m'envoyer les informations ?\">Pourriez-vous m'envoyer les informations ?</span>（您能把信息发给我吗？）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，命令式 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：简单条件式","body":"今天再回 grammar-a1a2.html#conditionnel-present 看一遍 简单条件式，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#conditionnel-present","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:命令式"}]}]},{"day":3,"theme":"精听 · 对话页的 d08、d12、d09 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d08、d12、d09 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d08","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5025","level":"A1","skill":"listening","prompt":"在药店听到 « Sur ordonnance ? » 是在问？","options":["有没有处方","要不要发票","付现金吗"],"answer":"有没有处方","explain":"ordonnance 是处方，药店常问药是否需要凭处方购买。","source":"词汇 · 就医"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听 3 段服务场景对话（药店、邮局、银行），写出关键信息与礼貌用语。","src":"dialogue.html#d08","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span>（请）、<span class=\"fr\" data-fr=\"excusez-moi\">excusez-moi</span>（请原谅）、<span class=\"fr\" data-fr=\"je voudrais\">je voudrais</span>（我想要）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t25","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「命令式 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d08","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · 礼貌表达、日常请求与正式书信格式","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：模拟请求、道歉、拒绝、道谢各 3 句，语气要得体，拒绝时要给理由。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5014","level":"A1","skill":"speaking","prompt":"礼貌拒绝邀请，最得体的说法是？","options":["Je suis désolé, mais je ne peux pas venir.","Non.","Je ne viens pas, c'est tout."],"answer":"Je suis désolé, mais je ne peux pas venir.","explain":"礼貌拒绝要先致歉再说明理由，直接说 Non 显得无礼。","source":"语法 · 礼貌表达"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d08、d12、d09 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、命令式 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d08","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une demande\">une demande</span>（请求）、<span class=\"fr\" data-fr=\"un renseignement\">un renseignement</span>（信息；咨询）、<span class=\"fr\" data-fr=\"cordialement\">cordialement</span>（此致（落款））轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t25 再看一遍例句。","src":"vocab.html#t25","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · 礼貌表达、日常请求与正式书信格式","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读对话页 A1 药店与地铁买票篇，圈出所有礼貌结构。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5023","level":"A1","skill":"reading","prompt":"正式邮件开头应写？","options":["Madame, Monsieur,","Salut,","Bonjour mon ami,"],"answer":"Madame, Monsieur,","explain":"不知道收件人姓名时用 Madame, Monsieur,；Salut 只用于熟人之间。","source":"词汇 · 书信格式"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span>（请）、<span class=\"fr\" data-fr=\"excusez-moi\">excusez-moi</span>（请原谅）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t25","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#imperatif，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#imperatif","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:命令式"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「命令式」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · 礼貌表达、日常请求与正式书信格式","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写一封 80 词邮件（向房东或学校询问信息），格式与落款都要正确。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5012","level":"A1","skill":"writing","prompt":"邮件中「请把资料寄给我」最得体的说法是？","options":["Pourriez-vous m'envoyer les documents ?","Envoyez-moi les documents.","Tu envoies les documents."],"answer":"Pourriez-vous m'envoyer les documents ?","explain":"条件式加 vous 是正式请求的标准结构；命令式与 tu 都不适合正式邮件。","source":"语法 · 条件式礼貌用法"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#imperatif，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#imperatif","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:命令式"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「命令式」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span>（请）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · 礼貌表达、日常请求与正式书信格式","type":"review","steps":[{"type":"review","title":"本周回顾：礼貌表达、日常请求与正式书信格式","body":"这一周围绕「礼貌表达、日常请求与正式书信格式」展开：语法主线是 命令式，词汇主线是 高频动词与万能表达。先用 3 句话口头复述本周学了什么，再打开日历页第 12 周清单逐条核对里程碑。","src":"calendar.html#wk-12","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"语法复盘：命令式","body":"从 grammar-a1a2.html#imperatif 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#imperatif","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:命令式"}]},{"type":"review","title":"词汇自测：高频动词与万能表达","body":"遮住中文看 vocab.html#t25 的 6 个核心词：<span class=\"fr\" data-fr=\"s'il vous plaît\">s'il vous plaît</span> <span class=\"fr\" data-fr=\"excusez-moi\">excusez-moi</span> <span class=\"fr\" data-fr=\"je voudrais\">je voudrais</span> <span class=\"fr\" data-fr=\"une demande\">une demande</span> <span class=\"fr\" data-fr=\"un renseignement\">un renseignement</span> <span class=\"fr\" data-fr=\"cordialement\">cordialement</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t25","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5045","level":"A1","skill":"vocab","prompt":"« excusez-moi » 用于？","options":["道歉或引起注意","道谢","告别"],"answer":"道歉或引起注意","explain":"excusez-moi 用于道歉或礼貌地打断对方；merci 是道谢；au revoir 是告别。","source":"词汇 · 礼貌用语"},{"id":"q-vocab-a1-5046","level":"A1","skill":"vocab","prompt":"「银行」用法语说是？","options":["la banque","la poste","la gare"],"answer":"la banque","explain":"banque 是银行；la poste 是邮局；la gare 是火车站。","source":"词汇 · 办事场景"},{"ref":"bank:vocab:A2:高频动词与万能表达"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d08","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5026","level":"A1","skill":"listening","prompt":"听到 « Un instant, s'il vous plaît. » 表示？","options":["请稍等","请再说一遍","请签字"],"answer":"请稍等","explain":"un instant 表示一会儿，这句话是「请稍等」的礼貌说法。","source":"词汇 · 服务场景"},{"id":"q-read-a1-5024","level":"A1","skill":"reading","prompt":"求助信里必须避免的是？","options":["混用 tu 与 vous","写落款","分段"],"answer":"混用 tu 与 vous","explain":"正式信函全文必须统一用 vous，混用会显得不专业。","source":"词汇 · 书信格式"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 命令式 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#imperatif 再核对一次。","src":"grammar-a1a2.html#conditionnel-present","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5045","level":"A1","skill":"grammar","prompt":"对 vous 提要求时应说（attendre）？","options":["Attendez !","Attends !","Attendons !"],"answer":"Attendez !","explain":"对 vous 用 -ez 结尾的 Attendez；Attends 给 tu，Attendons 包含说话人自己。","source":"语法 · 命令式"},{"id":"q-gram-a1-5046","level":"A1","skill":"grammar","prompt":"下列哪个结构最适合正式邮件中的请求？","options":["Je vous prie de…","Je veux que tu…","Donne-moi…"],"answer":"Je vous prie de…","explain":"Je vous prie de + 不定式是正式的书面请求结构，其余两个过于口语或失礼。","source":"语法 · 书面礼貌"},{"ref":"bank:grammar:A1:命令式"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":13,"level":"A1","theme":"阶段测：A1 全项模拟与复盘（词汇 600）","days":[{"day":1,"theme":"词汇 · 人与身份","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：人与身份","body":"本周词汇主战场是人与身份（L'être humain et l'identité）。先到 vocab.html#t1 把词表扫一遍，把 <span class=\"fr\" data-fr=\"se présenter\">se présenter</span>（自我介绍）、<span class=\"fr\" data-fr=\"un exercice\">un exercice</span>（练习）、<span class=\"fr\" data-fr=\"une erreur\">une erreur</span>（错误）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t1","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a1-5047","level":"A1","skill":"vocab","prompt":"« une erreur » 的意思是？","options":["错误","练习","答案"],"answer":"错误","explain":"erreur 是错误；exercice 是练习；réponse 是答案。","source":"词汇 · 学习"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"vocab","title":"搭配与辨析：une réponse / un niveau","body":"把 <span class=\"fr\" data-fr=\"une réponse\">une réponse</span>（答案）和 <span class=\"fr\" data-fr=\"un niveau\">un niveau</span>（水平）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t1","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a1-5048","level":"A1","skill":"vocab","prompt":"« progresser » 的意思是？","options":["进步","复习","提问"],"answer":"进步","explain":"progresser 是进步、提高；réviser 是复习；demander 是提问。","source":"词汇 · 学习"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"listen","title":"听音辨词：人与身份","body":"打开 对话页的 d12 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"progresser\">progresser</span>（进步）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d12","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je m'appelle Léa et j'habite à Tours.\">Je m'appelle Léa et j'habite à Tours.</span>（我叫莱娅，我住在图尔。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"vocab","title":"日终自测：人与身份 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"se présenter\">se présenter</span> <span class=\"fr\" data-fr=\"un exercice\">un exercice</span> <span class=\"fr\" data-fr=\"une erreur\">une erreur</span> <span class=\"fr\" data-fr=\"une réponse\">une réponse</span> <span class=\"fr\" data-fr=\"un niveau\">un niveau</span> <span class=\"fr\" data-fr=\"progresser\">progresser</span>。说不出来的词立刻回到 vocab.html#t1 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t1","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:人与身份"}]}]},{"day":2,"theme":"语法 · 现在时总复习","type":"grammar","steps":[{"type":"grammar","title":"语法点：现在时总复习","body":"【现在时总复习】这一周不学新内容，只做检测与补漏：前 12 周的语法集中在冠词、现在时三组变位、代词、否定、疑问与最近将来，词汇目标约 600 词。关键不是再读一遍，而是限时做题后把错题按「时态 / 冠词 / 代词 / 语序」分类。 例句：<span class=\"fr\" data-fr=\"Je m'appelle Léa et j'habite à Tours.\">Je m'appelle Léa et j'habite à Tours.</span>（我叫莱娅，我住在图尔。）；<span class=\"fr\" data-fr=\"Est-ce que vous avez des questions ?\">Est-ce que vous avez des questions ?</span>（你们有问题吗？）。对照 grammar-a1a2.html#present 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#present","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a1-5047","level":"A1","skill":"grammar","prompt":"「我住在巴黎」正确说法是？","options":["J'habite à Paris.","Je habite à Paris.","J'habite en Paris."],"answer":"J'habite à Paris.","explain":"je 在元音前省音成 j'；城市前用 à，国家才用 en。","source":"语法 · 现在时与介词"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 现在时总复习 的规则和两个例句，再打开 grammar-a1a2.html#present 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#present","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a1-5048","level":"A1","skill":"grammar","prompt":"« ___ enfants jouent dans le jardin. » 应填？","options":["Les","Des","Un"],"answer":"Les","explain":"特指已知的孩子们用定冠词 Les；Des 表不确定数量。","source":"语法 · 冠词"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"read","title":"在短文里找现在时总复习","body":"在 grammar-a1a2.html#present 的例句和章末小测里挑 5 句，圈出所有属于「现在时总复习」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#present","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je m'appelle Léa et j'habite à Tours.\">Je m'appelle Léa et j'habite à Tours.</span>（我叫莱娅，我住在图尔。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，现在时总复习 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"语法点巩固：冠词总复习","body":"今天再回 grammar-a1a2.html#articles 看一遍 冠词总复习，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#articles","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A1:现在时"}]}]},{"day":3,"theme":"精听 · 对话页的 d12 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d12 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d12","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a1-5027","level":"A1","skill":"listening","prompt":"听到 /ɛskə vu zave de kɛstjɔ̃/ 对应写法是？","options":["Est-ce que vous avez des questions ?","Vous avez des questions.","Avez-vous des questions ?"],"answer":"Est-ce que vous avez des questions ?","explain":"/ɛskə/ 是 est-ce que，后面主语与动词保持陈述语序。","source":"语法 · 疑问三式"},{"ref":"bank:listening:A1:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：用考试页的 A1/A2 级材料做听力 20 题，限时完成，错题当场标出原因。","src":"dialogue.html#d12","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"se présenter\">se présenter</span>（自我介绍）、<span class=\"fr\" data-fr=\"un exercice\">un exercice</span>（练习）、<span class=\"fr\" data-fr=\"une erreur\">une erreur</span>（错误）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t1","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「现在时总复习 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d12","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A1:听力"}]}]},{"day":4,"theme":"口语 · A1 全项模拟与复盘（词汇 600）","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：录一段 2 分钟自述（我的一天、我的家庭、我的城市），回听并标出 5 个问题。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a1-5015","level":"A1","skill":"speaking","prompt":"2 分钟自述里，表达年龄应该用？","options":["avoir 的变位","être 的变位","aller 的变位"],"answer":"avoir 的变位","explain":"法语年龄用 avoir：J'ai vingt ans，这是 A1 最常考也最常错的点。","source":"语法 · 年龄表达"},{"ref":"bank:speaking:A1:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A1:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d12 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、现在时总复习 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d12","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A1:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"une réponse\">une réponse</span>（答案）、<span class=\"fr\" data-fr=\"un niveau\">un niveau</span>（水平）、<span class=\"fr\" data-fr=\"progresser\">progresser</span>（进步）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t1 再看一遍例句。","src":"vocab.html#t1","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":5,"theme":"精读 · A1 全项模拟与复盘（词汇 600）","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：用词汇页 A1 筛选做自测，目标认词率不低于 85%（约 600 词）。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a1-5025","level":"A1","skill":"reading","prompt":"A1 阶段认词率的目标是？","options":["不低于 85%","不低于 60%","必须达到 100%"],"answer":"不低于 85%","explain":"课程表给出的里程碑是 A1 约 600 词认词率不低于 85%。","source":"词汇 · 阶段目标"},{"ref":"bank:reading:A1:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「现在时总复习」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"se présenter\">se présenter</span>（自我介绍）、<span class=\"fr\" data-fr=\"un exercice\">un exercice</span>（练习）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t1","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#present，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#present","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「现在时总复习」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A1:写作"}]}]},{"day":6,"theme":"写作 · A1 全项模拟与复盘（词汇 600）","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：限时写 80 词短文一篇，写完按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项自评。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a1-5013","level":"A1","skill":"writing","prompt":"写作自评的五项里，哪一项检查语法？","options":["变位与配合","字数","标点"],"answer":"变位与配合","explain":"语法项检查变位、性数配合与句法结构；字数属于任务完成度。","source":"写作 · 自评标准"},{"ref":"bank:writing:A1:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A1:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#present，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#present","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「现在时总复习」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A1:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"se présenter\">se présenter</span>（自我介绍）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A1:口语"}]}]},{"day":7,"theme":"复盘 · A1 全项模拟与复盘（词汇 600）","type":"review","steps":[{"type":"review","title":"本周回顾：阶段测：A1 全项模拟与复盘（词汇 600）","body":"这一周围绕「阶段测：A1 全项模拟与复盘（词汇 600）」展开：语法主线是 现在时总复习，词汇主线是 人与身份。先用 3 句话口头复述本周学了什么，再打开日历页第 13 周清单逐条核对里程碑。","src":"calendar.html#wk-13","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"语法复盘：现在时总复习","body":"从 grammar-a1a2.html#present 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#present","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"词汇自测：人与身份","body":"遮住中文看 vocab.html#t1 的 6 个核心词：<span class=\"fr\" data-fr=\"se présenter\">se présenter</span> <span class=\"fr\" data-fr=\"un exercice\">un exercice</span> <span class=\"fr\" data-fr=\"une erreur\">une erreur</span> <span class=\"fr\" data-fr=\"une réponse\">une réponse</span> <span class=\"fr\" data-fr=\"un niveau\">un niveau</span> <span class=\"fr\" data-fr=\"progresser\">progresser</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t1","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a1-5049","level":"A1","skill":"vocab","prompt":"« se présenter » 的意思是？","options":["自我介绍","提问","复述"],"answer":"自我介绍","explain":"se présenter 是自我介绍；poser une question 是提问；résumer 是复述。","source":"词汇 · 人与身份"},{"id":"q-vocab-a1-5050","level":"A1","skill":"vocab","prompt":"« un niveau » 的意思是？","options":["水平","笔记","考试"],"answer":"水平","explain":"niveau 是水平、等级；note 是笔记或分数；examen 是考试。","source":"词汇 · 学习"},{"ref":"bank:vocab:A1:人与身份"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d12","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a1-5028","level":"A1","skill":"listening","prompt":"阶段测听力里的第一步应该是？","options":["先读题再听","边听边抄","只听不记"],"answer":"先读题再听","explain":"先扫题干抓关键词，再带着问题听，抓取效率会明显提高。","source":"考试 · 听力策略"},{"id":"q-read-a1-5026","level":"A1","skill":"reading","prompt":"把错题分类时，下面哪一类属于「语序」问题？","options":["代词位置放错","动词变位错","单词拼错"],"answer":"代词位置放错","explain":"代词在动词前还是后属于语序；变位属于时态，拼写属于词汇与书写。","source":"语法 · 复习策略"},{"ref":"bank:listening:A1:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 现在时总复习 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#present 再核对一次。","src":"grammar-a1a2.html#articles","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a1-5049","level":"A1","skill":"grammar","prompt":"« Nous ___ étudiants. »（être）","options":["sommes","sont","êtes"],"answer":"sommes","explain":"nous 对应 sommes；sont 给 ils / elles，êtes 给 vous。","source":"语法 · être 现在时"},{"id":"q-gram-a1-5050","level":"A1","skill":"grammar","prompt":"下列哪句是否定句？","options":["Il ne travaille pas.","Il travaille.","Il va travailler."],"answer":"Il ne travaille pas.","explain":"ne…pas 构成否定；第二句是陈述，第三句是最近将来。","source":"语法 · 否定"},{"ref":"bank:grammar:A1:现在时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A1:写作"}]}]}]},{"week":14,"level":"A2","theme":"复合过去时（一）：avoir 助动词与过去分词","days":[{"day":1,"theme":"词汇 · 城市与交通","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：城市与交通","body":"城市与交通（La ville et les transports）是这一周要反复见面的主题域。打开 vocab.html#t9，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"visiter\">visiter</span>（参观）、<span class=\"fr\" data-fr=\"finir\">finir</span>（完成）、<span class=\"fr\" data-fr=\"prendre\">prendre</span>（拿；乘坐）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t9","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5001","level":"A2","skill":"vocab","prompt":"« visiter » 的过去分词是？","options":["visité","visiter","visitais"],"answer":"visité","explain":"-er 动词的过去分词把词尾换成 é：visiter 变 visité。","source":"语法 · 复合过去时"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"vocab","title":"搭配与辨析：faire / hier","body":"<span class=\"fr\" data-fr=\"faire\">faire</span>（做）与 <span class=\"fr\" data-fr=\"hier\">hier</span>（昨天）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t9","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5002","level":"A2","skill":"vocab","prompt":"« hier » 的意思是？","options":["昨天","今天","明天"],"answer":"昨天","explain":"hier 是昨天；aujourd'hui 是今天；demain 是明天。","source":"词汇 · 时间"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"listen","title":"听音辨词：城市与交通","body":"打开 对话页的 d17 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"un musée\">un musée</span>（博物馆）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d17","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Hier, j'ai visité le musée avec mes amis.\">Hier, j'ai visité le musée avec mes amis.</span>（昨天我和朋友们参观了博物馆。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：城市与交通 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"visiter\">visiter</span> <span class=\"fr\" data-fr=\"finir\">finir</span> <span class=\"fr\" data-fr=\"prendre\">prendre</span> <span class=\"fr\" data-fr=\"faire\">faire</span> <span class=\"fr\" data-fr=\"hier\">hier</span> <span class=\"fr\" data-fr=\"un musée\">un musée</span>。说不出来的词立刻回到 vocab.html#t9 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t9","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]}]},{"day":2,"theme":"语法 · 复合过去时","type":"grammar","steps":[{"type":"grammar","title":"语法点：复合过去时","body":"【复合过去时】复合过去时由助动词 avoir 或 être 的现在时加过去分词构成。多数动词用 avoir，过去分词的规律是 -er 变 é、-ir 变 i、-re 变 u，不规则分词要单独背：fait, pris, venu, eu, été。用 avoir 作助动词时，过去分词一般不与主语配合。 例句：<span class=\"fr\" data-fr=\"Hier, j'ai visité le musée avec mes amis.\">Hier, j'ai visité le musée avec mes amis.</span>（昨天我和朋友们参观了博物馆。）；<span class=\"fr\" data-fr=\"Nous avons fini le travail à six heures.\">Nous avons fini le travail à six heures.</span>（我们六点完成了工作。）。对照 grammar-a1a2.html#passe-compose 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#passe-compose","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5001","level":"A2","skill":"grammar","prompt":"Hier, j'___ mangé au restaurant.","options":["ai","suis","as"],"answer":"ai","explain":"manger 用 avoir 作助动词，je 对应 ai。","source":"语法 · 复合过去时"},{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#passe-compose 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Hier, j'ai visité le musée avec mes amis.\">Hier, j'ai visité le musée avec mes amis.</span>（昨天我和朋友们参观了博物馆。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#passe-compose","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5002","level":"A2","skill":"grammar","prompt":"« prendre » 的过去分词是？","options":["pris","prendu","prendé"],"answer":"pris","explain":"prendre 的过去分词是不规则的 pris，不能按 -re 变 u 的规律直推。","source":"语法 · 过去分词"},{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"read","title":"在短文里找复合过去时","body":"在 grammar-a1a2.html#passe-compose 的例句和章末小测里挑 5 句，圈出所有属于「复合过去时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#passe-compose","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Hier, j'ai visité le musée avec mes amis.\">Hier, j'ai visité le musée avec mes amis.</span>（昨天我和朋友们参观了博物馆。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，复合过去时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：时态总览","body":"今天再回 grammar-a1a2.html#temps 看一遍 时态总览，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#temps","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d17 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d17 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d17","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5001","level":"A2","skill":"listening","prompt":"听到 /ʒe fɛ/ 时最可能是？","options":["J'ai fait.","Je fais.","J'ai fini."],"answer":"J'ai fait.","explain":"/ʒe fɛ/ 是 j'ai 加 fait 的连读；Je fais 读 /ʒə fɛ/，没有 /e/ 这个音。","source":"语音 · 复合过去时读音"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段周末讲述，列出所有过去分词并写出动词原形。","src":"dialogue.html#d17","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"visiter\">visiter</span>（参观）、<span class=\"fr\" data-fr=\"finir\">finir</span>（完成）、<span class=\"fr\" data-fr=\"prendre\">prendre</span>（拿；乘坐）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t9","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「复合过去时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d17","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · avoir 助动词与过去分词","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：讲述「上个周末」2 分钟，全部使用复合过去时，时间顺序用 d'abord / ensuite / enfin 串起来。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5001","level":"A2","skill":"speaking","prompt":"讲上个周末时，叙述顺序词应该用？","options":["d'abord / ensuite / enfin","hier / demain / aujourd'hui","oui / non / peut-être"],"answer":"d'abord / ensuite / enfin","explain":"时间顺序连接词用 d'abord、ensuite、puis、enfin，能把事件串成一条线。","source":"语法 · 叙事连接"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d17 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、复合过去时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d17","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"faire\">faire</span>（做）、<span class=\"fr\" data-fr=\"hier\">hier</span>（昨天）、<span class=\"fr\" data-fr=\"un musée\">un musée</span>（博物馆）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t9 再看一遍例句。","src":"vocab.html#t9","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · avoir 助动词与过去分词","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页复合过去时（avoir）章节与不规则分词表，把 30 个常用分词抄一遍。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5001","level":"A2","skill":"reading","prompt":"« Nous avons fini. » 中 fini 与原形 finir 的关系是？","options":["过去分词","现在时变位","不定式"],"answer":"过去分词","explain":"-ir 动词的过去分词把词尾换成 i：finir 变 fini。","source":"语法 · 过去分词"},{"ref":"bank:reading:A2:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"visiter\">visiter</span>（参观）、<span class=\"fr\" data-fr=\"finir\">finir</span>（完成）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t9","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#passe-compose，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#passe-compose","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「复合过去时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · avoir 助动词与过去分词","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 120 词记叙：上周做过的事，注意时间顺序连接词。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5001","level":"A2","skill":"writing","prompt":"「我昨天做完了作业」正确写法是？","options":["Hier, j'ai fini mes devoirs.","Hier, je finis mes devoirs.","Hier, j'ai finir mes devoirs."],"answer":"Hier, j'ai fini mes devoirs.","explain":"复合过去时是助动词加过去分词，后面不能再用不定式 finir 的原形。","source":"语法 · 复合过去时"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#passe-compose，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#passe-compose","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「复合过去时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"visiter\">visiter</span>（参观）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · avoir 助动词与过去分词","type":"review","steps":[{"type":"review","title":"本周回顾：复合过去时（一）：avoir 助动词与过去分词","body":"这一周围绕「复合过去时（一）：avoir 助动词与过去分词」展开：语法主线是 复合过去时，词汇主线是 城市与交通。先用 3 句话口头复述本周学了什么，再打开日历页第 14 周清单逐条核对里程碑。","src":"calendar.html#wk-14","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"review","title":"语法复盘：复合过去时","body":"从 grammar-a1a2.html#passe-compose 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#passe-compose","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"review","title":"词汇自测：城市与交通","body":"遮住中文看 vocab.html#t9 的 6 个核心词：<span class=\"fr\" data-fr=\"visiter\">visiter</span> <span class=\"fr\" data-fr=\"finir\">finir</span> <span class=\"fr\" data-fr=\"prendre\">prendre</span> <span class=\"fr\" data-fr=\"faire\">faire</span> <span class=\"fr\" data-fr=\"hier\">hier</span> <span class=\"fr\" data-fr=\"un musée\">un musée</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t9","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5003","level":"A2","skill":"vocab","prompt":"« un musée » 的意思是？","options":["博物馆","电影院","图书馆"],"answer":"博物馆","explain":"musée 是博物馆；cinéma 是电影院；bibliothèque 是图书馆。","source":"词汇 · 文化与娱乐"},{"id":"q-vocab-a2-5004","level":"A2","skill":"vocab","prompt":"「完成」用法语说是？","options":["finir","visiter","commencer"],"answer":"finir","explain":"finir 是完成、结束；visiter 是参观；commencer 是开始。","source":"词汇 · 高频动词"},{"ref":"bank:vocab:A1:城市与交通"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d17","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5002","level":"A2","skill":"listening","prompt":"听到 /ɛl a fini/ 时表示？","options":["她完成了","她将要完成","她正在完成"],"answer":"她完成了","explain":"avoir 的现在时加过去分词构成复合过去时，表示已经完成的动作。","source":"语法 · 复合过去时"},{"id":"q-read-a2-5002","level":"A2","skill":"reading","prompt":"「我参观过这个博物馆」应说？","options":["J'ai visité ce musée.","Je visite ce musée.","Je vais visiter ce musée."],"answer":"J'ai visité ce musée.","explain":"谈论已经完成的经历用复合过去时。","source":"语法 · 复合过去时"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 复合过去时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#passe-compose 再核对一次。","src":"grammar-a1a2.html#temps","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5003","level":"A2","skill":"grammar","prompt":"« Ils ___ pris le train. »","options":["ont","sont","avez"],"answer":"ont","explain":"prendre 用 avoir 作助动词，ils 对应 ont。","source":"语法 · 复合过去时"},{"id":"q-gram-a2-5004","level":"A2","skill":"grammar","prompt":"下列哪个过去分词形式不存在？","options":["prendu","pris","fait"],"answer":"prendu","explain":"prendre 的过去分词是 pris，不存在 prendu 这种形式。","source":"语法 · 过去分词"},{"ref":"bank:grammar:A2:复合过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":15,"level":"A2","theme":"复合过去时（二）：être 助动词与过去分词配合","days":[{"day":1,"theme":"词汇 · 旅行与度假","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：旅行与度假","body":"本周词汇主战场是旅行与度假（Les voyages et les vacances）。先到 vocab.html#t10 把词表扫一遍，把 <span class=\"fr\" data-fr=\"partir\">partir</span>（出发）、<span class=\"fr\" data-fr=\"arriver\">arriver</span>（到达）、<span class=\"fr\" data-fr=\"descendre\">descendre</span>（下来；下车）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t10","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5005","level":"A2","skill":"vocab","prompt":"« la veille » 的意思是？","options":["前一天","第二天","同一天"],"answer":"前一天","explain":"la veille 指某个时间点的前一天；le lendemain 是第二天。","source":"词汇 · 时间"},{"ref":"bank:vocab:A1:旅行与度假"}]},{"type":"vocab","title":"搭配与辨析：se lever / la veille","body":"把 <span class=\"fr\" data-fr=\"se lever\">se lever</span>（起床）和 <span class=\"fr\" data-fr=\"la veille\">la veille</span>（前一天）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t10","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5006","level":"A2","skill":"vocab","prompt":"« un séjour » 的意思是？","options":["逗留；住宿","车票","行李"],"answer":"逗留；住宿","explain":"séjour 指在某地停留的时间；billet 是票；bagage 是行李。","source":"词汇 · 旅行"},{"ref":"bank:vocab:A1:旅行与度假"}]},{"type":"listen","title":"听音辨词：旅行与度假","body":"打开 对话页的 d18 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"le séjour\">le séjour</span>（逗留；住宿）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d18","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Marie est partie à Nice la semaine dernière.\">Marie est partie à Nice la semaine dernière.</span>（玛丽上周去了尼斯。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：旅行与度假 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"partir\">partir</span> <span class=\"fr\" data-fr=\"arriver\">arriver</span> <span class=\"fr\" data-fr=\"descendre\">descendre</span> <span class=\"fr\" data-fr=\"se lever\">se lever</span> <span class=\"fr\" data-fr=\"la veille\">la veille</span> <span class=\"fr\" data-fr=\"le séjour\">le séjour</span>。说不出来的词立刻回到 vocab.html#t10 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t10","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:旅行与度假"}]}]},{"day":2,"theme":"语法 · être 助动词与分词配合","type":"grammar","steps":[{"type":"grammar","title":"语法点：être 助动词与分词配合","body":"【être 助动词与分词配合】表示位移与状态变化的动词（aller, venir, arriver, partir, entrer, sortir, naître, mourir 等，合称 DR MRS VANDERTRAMP）用 être 作助动词，过去分词必须与主语性数配合：Elle est allée。代词式动词的复合过去时一律用 être，自反代词放在助动词前。 例句：<span class=\"fr\" data-fr=\"Marie est partie à Nice la semaine dernière.\">Marie est partie à Nice la semaine dernière.</span>（玛丽上周去了尼斯。）；<span class=\"fr\" data-fr=\"Nous nous sommes levés à six heures.\">Nous nous sommes levés à six heures.</span>（我们六点起床。）。对照 grammar-a1a2.html#etre-passe 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#etre-passe","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5005","level":"A2","skill":"grammar","prompt":"Elle ___ allée au marché.","options":["est","a","sont"],"answer":"est","explain":"aller 用 être 作助动词，elle 对应 est，过去分词配合加 -e 写成 allée。","source":"语法 · 复合过去时（être）"},{"ref":"bank:grammar:A2:助动词"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 être 助动词与分词配合 的规则和两个例句，再打开 grammar-a1a2.html#etre-passe 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-a1a2.html#etre-passe","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5006","level":"A2","skill":"grammar","prompt":"« Elles sont ___ hier. »（partir）","options":["parties","partis","parti"],"answer":"parties","explain":"主语 elles 是阴性复数，过去分词要加 -es 写成 parties。","source":"语法 · 过去分词配合"},{"ref":"bank:grammar:A2:助动词"}]},{"type":"read","title":"在短文里找être 助动词与分词配合","body":"在 grammar-a1a2.html#etre-passe 的例句和章末小测里挑 5 句，圈出所有属于「être 助动词与分词配合」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#etre-passe","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Marie est partie à Nice la semaine dernière.\">Marie est partie à Nice la semaine dernière.</span>（玛丽上周去了尼斯。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，être 助动词与分词配合 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：复合过去时","body":"今天再回 grammar-a1a2.html#passe-compose 看一遍 复合过去时，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#passe-compose","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:助动词"}]}]},{"day":3,"theme":"精听 · 对话页的 d18 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d18 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d18","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5003","level":"A2","skill":"listening","prompt":"听到 /ilsɔ̃taʁive/ 时表示？","options":["他们到了","他们要到","他们正在到"],"answer":"他们到了","explain":"être 加过去分词构成复合过去时；sont 与元音开头的 arrivés 之间联诵，读成 /ilsɔ̃taʁive/。","source":"语法 · 复合过去时（être）"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段旅行经历，专门标记 aller / venir / partir / arriver 的助动词与配合。","src":"dialogue.html#d18","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"partir\">partir</span>（出发）、<span class=\"fr\" data-fr=\"arriver\">arriver</span>（到达）、<span class=\"fr\" data-fr=\"descendre\">descendre</span>（下来；下车）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t10","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:旅行与度假"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「être 助动词与分词配合 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d18","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · être 助动词与过去分词配合","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：讲一次真实旅行（出发、到达、做了什么、感受）3 分钟，所有 être 助动词句必须配合正确。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5002","level":"A2","skill":"speaking","prompt":"讲旅行经历时，「我们六点起床」应说？","options":["Nous nous sommes levés à six heures.","Nous avons levé à six heures.","Nous sommes lever à six heures."],"answer":"Nous nous sommes levés à six heures.","explain":"代词式动词的复合过去时用 être，自反代词 nous 放在助动词前，分词配合成 levés。","source":"语法 · 代词式动词与复合过去时"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d18 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、être 助动词与分词配合 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d18","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"se lever\">se lever</span>（起床）、<span class=\"fr\" data-fr=\"la veille\">la veille</span>（前一天）、<span class=\"fr\" data-fr=\"le séjour\">le séjour</span>（逗留；住宿）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t10 再看一遍例句。","src":"vocab.html#t10","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:旅行与度假"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · être 助动词与过去分词配合","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页 être 助动词章节与配合规则表，把 DR MRS VANDERTRAMP 抄成一行口诀。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5003","level":"A2","skill":"reading","prompt":"下列哪一组动词用 être 作助动词？","options":["aller, venir, partir, arriver","manger, finir, parler","avoir, être, faire"],"answer":"aller, venir, partir, arriver","explain":"位移与状态变化类动词用 être；manger、finir、parler 与 faire 都用 avoir。","source":"语法 · 助动词选择"},{"ref":"bank:reading:A2:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「être 助动词与分词配合」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"partir\">partir</span>（出发）、<span class=\"fr\" data-fr=\"arriver\">arriver</span>（到达）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t10","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:旅行与度假"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#etre-passe，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#etre-passe","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:助动词"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「être 助动词与分词配合」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · être 助动词与过去分词配合","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 150 词旅行记叙，所有 être 助动词句的性数配合都要正确。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5002","level":"A2","skill":"writing","prompt":"「她昨天到了」正确写法是？","options":["Elle est arrivée hier.","Elle a arrivé hier.","Elle est arrivé hier."],"answer":"Elle est arrivée hier.","explain":"arriver 用 être，且过去分词要跟阴性主语配合，写成 arrivée。","source":"语法 · 过去分词配合"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#etre-passe，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#etre-passe","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:助动词"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「être 助动词与分词配合」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"partir\">partir</span>（出发）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · être 助动词与过去分词配合","type":"review","steps":[{"type":"review","title":"本周回顾：复合过去时（二）：être 助动词与过去分词配合","body":"这一周围绕「复合过去时（二）：être 助动词与过去分词配合」展开：语法主线是 être 助动词与分词配合，词汇主线是 旅行与度假。先用 3 句话口头复述本周学了什么，再打开日历页第 15 周清单逐条核对里程碑。","src":"calendar.html#wk-15","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:旅行与度假"}]},{"type":"review","title":"语法复盘：être 助动词与分词配合","body":"从 grammar-a1a2.html#etre-passe 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#etre-passe","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:助动词"}]},{"type":"review","title":"词汇自测：旅行与度假","body":"遮住中文看 vocab.html#t10 的 6 个核心词：<span class=\"fr\" data-fr=\"partir\">partir</span> <span class=\"fr\" data-fr=\"arriver\">arriver</span> <span class=\"fr\" data-fr=\"descendre\">descendre</span> <span class=\"fr\" data-fr=\"se lever\">se lever</span> <span class=\"fr\" data-fr=\"la veille\">la veille</span> <span class=\"fr\" data-fr=\"le séjour\">le séjour</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t10","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5007","level":"A2","skill":"vocab","prompt":"« descendre » 表位移时用哪类助动词？","options":["être","avoir","两者都不用"],"answer":"être","explain":"descendre 表「下来、下车」且不带宾语时用 être；作「取下某物」并带宾语时用 avoir。","source":"语法 · 助动词选择"},{"id":"q-vocab-a2-5008","level":"A2","skill":"vocab","prompt":"「到达」用法语说是？","options":["arriver","partir","rester"],"answer":"arriver","explain":"arriver 是到达；partir 是出发；rester 是停留。","source":"词汇 · 旅行"},{"ref":"bank:vocab:A1:旅行与度假"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d18","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5004","level":"A2","skill":"listening","prompt":"听到 /ɛl ɛ parti/ 时最可能是？","options":["Elle est partie.","Il est parti.","Elles sont parties."],"answer":"Elle est partie.","explain":"/ɛl ɛ/ 是 elle est，与 il est 的 /il ɛ/ 起头不同。","source":"语音 · 复合过去时读音"},{"id":"q-read-a2-5004","level":"A2","skill":"reading","prompt":"既然用了 être 作助动词，过去分词必须？","options":["与主语性数配合","始终保持原形","变成现在分词"],"answer":"与主语性数配合","explain":"être 作助动词时，过去分词要与主语保持性数一致，这是与 avoir 的关键差别。","source":"语法 · 过去分词配合"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 être 助动词与分词配合 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#etre-passe 再核对一次。","src":"grammar-a1a2.html#passe-compose","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5007","level":"A2","skill":"grammar","prompt":"« Nous ___ venus en train. »","options":["sommes","avons","sont"],"answer":"sommes","explain":"venir 用 être 作助动词，nous 对应 sommes，分词配合成 venus。","source":"语法 · 复合过去时（être）"},{"id":"q-gram-a2-5008","level":"A2","skill":"grammar","prompt":"下列哪句有配合或助动词错误？","options":["Elle a allée au cinéma.","Elle est allée au cinéma.","Elles sont allées au cinéma."],"answer":"Elle a allée au cinéma.","explain":"aller 必须用 être；用 avoir 还把分词配合成 allée，是双重错误。","source":"语法 · 助动词选择"},{"ref":"bank:grammar:A2:助动词"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":16,"level":"A2","theme":"未完成过去时：描写与习惯","days":[{"day":1,"theme":"词汇 · 情感与态度","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：情感与态度","body":"情感与态度（Les émotions et les attitudes）是这一周要反复见面的主题域。打开 vocab.html#t18，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"jouer\">jouer</span>（玩耍；踢）、<span class=\"fr\" data-fr=\"pleuvoir\">pleuvoir</span>（下雨）、<span class=\"fr\" data-fr=\"un souvenir\">un souvenir</span>（回忆）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t18","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5009","level":"A2","skill":"vocab","prompt":"« l'enfance » 的意思是？","options":["童年","青年","老年"],"answer":"童年","explain":"enfance 是童年；jeunesse 是青年时期；vieillesse 是老年。","source":"词汇 · 人生阶段"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"vocab","title":"搭配与辨析：l'enfance / toujours","body":"<span class=\"fr\" data-fr=\"l'enfance\">l'enfance</span>（童年）与 <span class=\"fr\" data-fr=\"toujours\">toujours</span>（总是）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t18","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5010","level":"A2","skill":"vocab","prompt":"« souvent » 的意思是？","options":["经常","总是","从不"],"answer":"经常","explain":"souvent 是经常；toujours 是总是；jamais 是从不。","source":"词汇 · 频率副词"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"listen","title":"听音辨词：情感与态度","body":"打开 对话页的 d24 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"souvent\">souvent</span>（经常）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d24","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Quand j'étais petit, je jouais au football tous les samedis.\">Quand j'étais petit, je jouais au football tous les samedis.</span>（我小时候每个周六都踢足球。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：情感与态度 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"jouer\">jouer</span> <span class=\"fr\" data-fr=\"pleuvoir\">pleuvoir</span> <span class=\"fr\" data-fr=\"un souvenir\">un souvenir</span> <span class=\"fr\" data-fr=\"l'enfance\">l'enfance</span> <span class=\"fr\" data-fr=\"toujours\">toujours</span> <span class=\"fr\" data-fr=\"souvent\">souvent</span>。说不出来的词立刻回到 vocab.html#t18 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t18","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]}]},{"day":2,"theme":"语法 · 未完成过去时","type":"grammar","steps":[{"type":"grammar","title":"语法点：未完成过去时","body":"【未完成过去时】未完成过去时的构成是「nous 现在时去掉 -ons 再加词尾 -ais, -ais, -ait, -ions, -iez, -aient」；être 是唯一例外，词干为 ét-。它用于描写背景、习惯与状态，而复合过去时用于推进事件，两者的分工是法语叙事的骨架。 例句：<span class=\"fr\" data-fr=\"Quand j'étais petit, je jouais au football tous les samedis.\">Quand j'étais petit, je jouais au football tous les samedis.</span>（我小时候每个周六都踢足球。）；<span class=\"fr\" data-fr=\"Il pleuvait et le ciel était gris.\">Il pleuvait et le ciel était gris.</span>（当时下着雨，天空灰蒙蒙的。）。对照 grammar-a1a2.html#imparfait 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#imparfait","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5009","level":"A2","skill":"grammar","prompt":"« Nous ___ au parc tous les dimanches. »（jouer，未完成过去时）","options":["jouions","jouons","jouerons"],"answer":"jouions","explain":"nous 的未完成过去时由 nous jouons 去掉 -ons 再加 -ions 得到 jouions。","source":"语法 · 未完成过去时"},{"ref":"bank:grammar:A2:未完成过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#imparfait 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Quand j'étais petit, je jouais au football tous les samedis.\">Quand j'étais petit, je jouais au football tous les samedis.</span>（我小时候每个周六都踢足球。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#imparfait","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5010","level":"A2","skill":"grammar","prompt":"未完成过去时中 être 的词干是？","options":["ét-","êt-","ser-"],"answer":"ét-","explain":"être 是唯一不规则词干：j'étais, tu étais, il était；ser- 是简单将来时的词干。","source":"语法 · 未完成过去时"},{"ref":"bank:grammar:A2:未完成过去时"}]},{"type":"read","title":"在短文里找未完成过去时","body":"在 grammar-a1a2.html#imparfait 的例句和章末小测里挑 5 句，圈出所有属于「未完成过去时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#imparfait","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Quand j'étais petit, je jouais au football tous les samedis.\">Quand j'étais petit, je jouais au football tous les samedis.</span>（我小时候每个周六都踢足球。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，未完成过去时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：三种过去时的分工","body":"今天再回 grammar-b1b2.html#recit-pc-imp 看一遍 三种过去时的分工，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#recit-pc-imp","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:未完成过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d24 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d24 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d24","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5005","level":"A2","skill":"listening","prompt":"听到 /il pløvɛ/ 时表示？","options":["当时在下雨","现在下雨","将要下雨"],"answer":"当时在下雨","explain":"pleuvoir 的未完成过去时用于描写过去某时的天气背景。","source":"语法 · 未完成过去时"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段童年回忆，统计未完成过去时与复合过去时各出现几次。","src":"dialogue.html#d24","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"jouer\">jouer</span>（玩耍；踢）、<span class=\"fr\" data-fr=\"pleuvoir\">pleuvoir</span>（下雨）、<span class=\"fr\" data-fr=\"un souvenir\">un souvenir</span>（回忆）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t18","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「未完成过去时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d24","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 描写与习惯","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：讲「我小时候」3 分钟，交替使用两种过去时。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5003","level":"A2","skill":"speaking","prompt":"讲童年回忆时，描写背景应该用？","options":["未完成过去时","复合过去时","简单将来时"],"answer":"未完成过去时","explain":"背景、习惯与状态用未完成过去时，事件推进用复合过去时。","source":"语法 · 两种过去时分工"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d24 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、未完成过去时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d24","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"l'enfance\">l'enfance</span>（童年）、<span class=\"fr\" data-fr=\"toujours\">toujours</span>（总是）、<span class=\"fr\" data-fr=\"souvent\">souvent</span>（经常）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t18 再看一遍例句。","src":"vocab.html#t18","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 描写与习惯","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页未完成过去时章节与用法清单，把六个词尾默写一遍。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5005","level":"A2","skill":"reading","prompt":"« Quand je suis arrivé, il dormait. » 中 dormait 的作用是？","options":["描写正在进行的背景动作","推进事件","表示将来的计划"],"answer":"描写正在进行的背景动作","explain":"dormait 是未完成过去时，为 arrivé 这个事件提供背景。","source":"语法 · 两种过去时分工"},{"ref":"bank:reading:A2:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"jouer\">jouer</span>（玩耍；踢）、<span class=\"fr\" data-fr=\"pleuvoir\">pleuvoir</span>（下雨）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t18","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#imparfait，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#imparfait","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:未完成过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「未完成过去时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 描写与习惯","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 120 词童年回忆，包含场景描写与一次具体事件的对比。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5003","level":"A2","skill":"writing","prompt":"「我小时候住在乡下」正确写法是？","options":["Quand j'étais petit, j'habitais à la campagne.","Quand j'étais petit, j'habite à la campagne.","Quand j'ai été petit, j'habitais à la campagne."],"answer":"Quand j'étais petit, j'habitais à la campagne.","explain":"描写过去的习惯状态时，主句与从句都用未完成过去时。","source":"语法 · 未完成过去时"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#imparfait，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#imparfait","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:未完成过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「未完成过去时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"jouer\">jouer</span>（玩耍；踢）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 描写与习惯","type":"review","steps":[{"type":"review","title":"本周回顾：未完成过去时：描写与习惯","body":"这一周围绕「未完成过去时：描写与习惯」展开：语法主线是 未完成过去时，词汇主线是 情感与态度。先用 3 句话口头复述本周学了什么，再打开日历页第 16 周清单逐条核对里程碑。","src":"calendar.html#wk-16","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"review","title":"语法复盘：未完成过去时","body":"从 grammar-a1a2.html#imparfait 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#imparfait","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:未完成过去时"}]},{"type":"review","title":"词汇自测：情感与态度","body":"遮住中文看 vocab.html#t18 的 6 个核心词：<span class=\"fr\" data-fr=\"jouer\">jouer</span> <span class=\"fr\" data-fr=\"pleuvoir\">pleuvoir</span> <span class=\"fr\" data-fr=\"un souvenir\">un souvenir</span> <span class=\"fr\" data-fr=\"l'enfance\">l'enfance</span> <span class=\"fr\" data-fr=\"toujours\">toujours</span> <span class=\"fr\" data-fr=\"souvent\">souvent</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t18","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5011","level":"A2","skill":"vocab","prompt":"« un souvenir » 的意思是？","options":["回忆","纪念品商店","梦境"],"answer":"回忆","explain":"souvenir 是回忆，也可以指纪念品；rêve 是梦。","source":"词汇 · 情感"},{"id":"q-vocab-a2-5012","level":"A2","skill":"vocab","prompt":"« pleuvoir » 的第三人称单数未完成过去时是？","options":["il pleuvait","il pleut","il pleuvra"],"answer":"il pleuvait","explain":"pleuvoir 是无人称动词，未完成过去时写作 il pleuvait。","source":"语法 · 未完成过去时"},{"ref":"bank:vocab:A2:情感与态度"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d24","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5006","level":"A2","skill":"listening","prompt":"听到 /ʒə ʒwɛ/ 时最可能是？","options":["Je jouais.","Je joue.","Je jouerai."],"answer":"Je jouais.","explain":"未完成过去时 je jouais 读 /ʒə ʒwɛ/；现在时 je joue 读 /ʒə ʒu/。","source":"语音 · 未完成过去时读音"},{"id":"q-read-a2-5006","level":"A2","skill":"reading","prompt":"「他总是迟到」应说？","options":["Il était toujours en retard.","Il a toujours en retard.","Il est toujours en retard hier."],"answer":"Il était toujours en retard.","explain":"表示过去的习惯用未完成过去时；复合过去时无法表达反复出现的习惯。","source":"语法 · 未完成过去时"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 未完成过去时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#imparfait 再核对一次。","src":"grammar-b1b2.html#recit-pc-imp","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5011","level":"A2","skill":"grammar","prompt":"« Vous ___ fatigués après le voyage. »（être，未完成过去时）","options":["étiez","êtes","serez"],"answer":"étiez","explain":"vous 的未完成过去时是 étiez，词干 ét- 加 -iez。","source":"语法 · 未完成过去时"},{"id":"q-gram-a2-5012","level":"A2","skill":"grammar","prompt":"下列哪句描写天气背景？","options":["Il faisait froid et le vent soufflait.","Il a fait froid hier.","Il fera froid demain."],"answer":"Il faisait froid et le vent soufflait.","explain":"两个未完成过去时并列，描写过去的天气背景；另外两句分别是一次事件与将来。","source":"语法 · 未完成过去时"},{"ref":"bank:grammar:A2:未完成过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":17,"level":"A2","theme":"两种过去时的分工与叙事骨架","days":[{"day":1,"theme":"词汇 · 抽象概念与逻辑","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：抽象概念与逻辑","body":"本周词汇主战场是抽象概念与逻辑（Les notions abstraites et la logique）。先到 vocab.html#t24 把词表扫一遍，把 <span class=\"fr\" data-fr=\"marcher\">marcher</span>（走路）、<span class=\"fr\" data-fr=\"voir\">voir</span>（看见）、<span class=\"fr\" data-fr=\"un accident\">un accident</span>（事故）抄在卡片正面。名词连着冠词一起记，动词连最常用的搭配一起记，边写边出声读。","src":"vocab.html#t24","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5013","level":"A2","skill":"vocab","prompt":"« tout à coup » 的意思是？","options":["突然","慢慢地","最后"],"answer":"突然","explain":"tout à coup 表示突然，常用于引出推进事件；peu à peu 是慢慢地。","source":"词汇 · 叙事连接"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"vocab","title":"搭配与辨析：pendant que / tout à coup","body":"把 <span class=\"fr\" data-fr=\"pendant que\">pendant que</span>（在……期间）和 <span class=\"fr\" data-fr=\"tout à coup\">tout à coup</span>（突然）放进同一个场景里各造一句，句子要主谓宾齐全。造完再把主语换成 il / elle 说一遍，检查冠词有没有跟着名词变。","src":"vocab.html#t24","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5014","level":"A2","skill":"vocab","prompt":"« un accident » 的意思是？","options":["事故","经历","约会"],"answer":"事故","explain":"accident 是事故；expérience 是经历；rendez-vous 是约会。","source":"词汇 · 事件"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"listen","title":"听音辨词：抽象概念与逻辑","body":"打开 对话页的 d17 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"ensuite\">ensuite</span>（然后）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d17","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Je marchais dans la rue quand j'ai vu un accident.\">Je marchais dans la rue quand j'ai vu un accident.</span>（我在街上走着，忽然看到一起事故。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：抽象概念与逻辑 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"marcher\">marcher</span> <span class=\"fr\" data-fr=\"voir\">voir</span> <span class=\"fr\" data-fr=\"un accident\">un accident</span> <span class=\"fr\" data-fr=\"pendant que\">pendant que</span> <span class=\"fr\" data-fr=\"tout à coup\">tout à coup</span> <span class=\"fr\" data-fr=\"ensuite\">ensuite</span>。说不出来的词立刻回到 vocab.html#t24 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t24","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]}]},{"day":2,"theme":"语法 · 三种过去时的分工","type":"grammar","steps":[{"type":"grammar","title":"语法点：三种过去时的分工","body":"【三种过去时的分工】叙事时，复合过去时负责「发生了什么」——推动情节的一次性事件；未完成过去时负责「当时是什么样」——背景、状态与习惯。常见搭配是 quand / lorsque 引出事件、pendant que 引出同时进行的背景。时态选错不会让句子不合法，但会让叙事层次混乱。 例句：<span class=\"fr\" data-fr=\"Je marchais dans la rue quand j'ai vu un accident.\">Je marchais dans la rue quand j'ai vu un accident.</span>（我在街上走着，忽然看到一起事故。）；<span class=\"fr\" data-fr=\"Pendant que je lisais, le téléphone a sonné.\">Pendant que je lisais, le téléphone a sonné.</span>（我正在看书时，电话响了。）。对照 grammar-b1b2.html#recit-pc-imp 的表格，把规则抄成自己的一句话。","src":"grammar-b1b2.html#recit-pc-imp","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5013","level":"A2","skill":"grammar","prompt":"« Je ___ quand le téléphone a sonné. »（lire，背景）","options":["lisais","ai lu","lirai"],"answer":"lisais","explain":"正在进行的背景动作用未完成过去时，事件 a sonné 用复合过去时。","source":"语法 · 两种过去时分工"},{"ref":"bank:grammar:A2:过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"先合上书，凭记忆写出 三种过去时的分工 的规则和两个例句，再打开 grammar-b1b2.html#recit-pc-imp 对照补漏，用红笔标出回忆失败的地方。回忆失败比再读一遍更有价值，那正是考试时会出错的位置。","src":"grammar-b1b2.html#recit-pc-imp","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5014","level":"A2","skill":"grammar","prompt":"« Pendant que » 一般引出？","options":["同时进行的背景","将要发生的事","反复出现的结果"],"answer":"同时进行的背景","explain":"pendant que 引出与另一动作同时进行的背景，常用未完成过去时。","source":"语法 · 时间连接词"},{"ref":"bank:grammar:A2:过去时"}]},{"type":"read","title":"在短文里找三种过去时的分工","body":"在 grammar-b1b2.html#recit-pc-imp 的例句和章末小测里挑 5 句，圈出所有属于「三种过去时的分工」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-b1b2.html#recit-pc-imp","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Je marchais dans la rue quand j'ai vu un accident.\">Je marchais dans la rue quand j'ai vu un accident.</span>（我在街上走着，忽然看到一起事故。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，三种过去时的分工 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：复合过去时 vs 未完成过去时","body":"今天再回 grammar-a1a2.html#pc-imparfait 看一遍 复合过去时 vs 未完成过去时，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-a1a2.html#pc-imparfait","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d17 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"打开 对话页的 d17 篇，盲听第一遍，不暂停、不看文本。只听一个问题：这段话在谈什么？用中文写一句概括，再写下 3 个听清的词。","src":"dialogue.html#d17","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5007","level":"A2","skill":"listening","prompt":"听到 /ʒə maʁʃɛ kɑ̃ ʒe vy/ 的结构是？","options":["背景（未完成）加事件（复合过去）","两个事件","两个背景"],"answer":"背景（未完成）加事件（复合过去）","explain":"marchais 是背景，ai vu 是事件，这是最典型的叙事骨架。","source":"语法 · 两种过去时分工"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听 2 段「发生意外」的故事，画出事件线与背景线。","src":"dialogue.html#d17","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"marcher\">marcher</span>（走路）、<span class=\"fr\" data-fr=\"voir\">voir</span>（看见）、<span class=\"fr\" data-fr=\"un accident\">un accident</span>（事故）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t24","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「三种过去时的分工 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d17","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 两种过去时的分工与叙事骨架","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：看图讲一个完整故事（起因、背景、事件、结果）3 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5004","level":"A2","skill":"speaking","prompt":"讲故事时的四步结构是？","options":["背景、事件、反应、结果","现在、将来、过去、现在","提问、回答、重复、总结"],"answer":"背景、事件、反应、结果","explain":"先交代背景（未完成过去时），再用事件推进（复合过去时），最后说结果。","source":"口语 · 叙事结构"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"把答案录在手机里，先说满 60 秒不停。说到一半忘词就先换一种说法把意思顶过去，流利度优先于用词精确。录完不要马上回听，隔十分钟再听一遍，判断会更客观。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d17 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、三种过去时的分工 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d17","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"pendant que\">pendant que</span>（在……期间）、<span class=\"fr\" data-fr=\"tout à coup\">tout à coup</span>（突然）、<span class=\"fr\" data-fr=\"ensuite\">ensuite</span>（然后）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t24 再看一遍例句。","src":"vocab.html#t24","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 两种过去时的分工与叙事骨架","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读对话页 A2 讲述过去篇与语法页对比章节，标出每句用的是哪种过去时。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5007","level":"A2","skill":"reading","prompt":"« Il pleuvait, alors j'ai pris un taxi. » 中两个时态的作用是？","options":["背景与随之发生的行动","两个并列事件","两个过去习惯"],"answer":"背景与随之发生的行动","explain":"pleuvait 提供背景，j'ai pris 是背景引发的具体行动。","source":"语法 · 两种过去时分工"},{"ref":"bank:reading:A2:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"挑文中 3 个超过 20 词的长句，先划出主谓宾，再把从句、分词、介词短语逐层挂上去。看到「三种过去时的分工」的结构就停下来确认触发条件。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"marcher\">marcher</span>（走路）、<span class=\"fr\" data-fr=\"voir\">voir</span>（看见）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t24","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-b1b2.html#recit-pc-imp，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-b1b2.html#recit-pc-imp","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「三种过去时的分工」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 两种过去时的分工与叙事骨架","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：写 150 词记叙文，需同时出现至少 6 个未完成过去时与 6 个复合过去时。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5004","level":"A2","skill":"writing","prompt":"「上周末我读完了这本书」正确写法是？","options":["Le week-end dernier, j'ai fini ce livre.","Le week-end dernier, je finissais ce livre.","Le week-end dernier, je finis ce livre."],"answer":"Le week-end dernier, j'ai fini ce livre.","explain":"一次完成的动作要用复合过去时；finissais 是习惯背景，finis 是现在时。","source":"语法 · 两种过去时分工"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"先写中文要点，再逐条译成法语，但译完必须回头改：把中文语序的句子打散重写，让动词和它的补语各就各位。改完把最生硬的 3 句抄到一边，作为下一稿的重点对象。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-b1b2.html#recit-pc-imp，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-b1b2.html#recit-pc-imp","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「三种过去时的分工」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"marcher\">marcher</span>（走路）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 两种过去时的分工与叙事骨架","type":"review","steps":[{"type":"review","title":"本周回顾：两种过去时的分工与叙事骨架","body":"这一周围绕「两种过去时的分工与叙事骨架」展开：语法主线是 三种过去时的分工，词汇主线是 抽象概念与逻辑。先用 3 句话口头复述本周学了什么，再打开日历页第 17 周清单逐条核对里程碑。","src":"calendar.html#wk-17","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"语法复盘：三种过去时的分工","body":"从 grammar-b1b2.html#recit-pc-imp 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-b1b2.html#recit-pc-imp","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:过去时"}]},{"type":"review","title":"词汇自测：抽象概念与逻辑","body":"遮住中文看 vocab.html#t24 的 6 个核心词：<span class=\"fr\" data-fr=\"marcher\">marcher</span> <span class=\"fr\" data-fr=\"voir\">voir</span> <span class=\"fr\" data-fr=\"un accident\">un accident</span> <span class=\"fr\" data-fr=\"pendant que\">pendant que</span> <span class=\"fr\" data-fr=\"tout à coup\">tout à coup</span> <span class=\"fr\" data-fr=\"ensuite\">ensuite</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t24","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5015","level":"A2","skill":"vocab","prompt":"« marcher » 的意思是？","options":["走路","跑步","开车"],"answer":"走路","explain":"marcher 是走路、行走；courir 是跑；conduire 是开车。","source":"词汇 · 高频动词"},{"id":"q-vocab-a2-5016","level":"A2","skill":"vocab","prompt":"「然后」用法语说是？","options":["ensuite","d'abord","enfin"],"answer":"ensuite","explain":"ensuite 是然后；d'abord 是先；enfin 是最后。","source":"词汇 · 叙事连接"},{"ref":"bank:vocab:A2:抽象概念与逻辑"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d17","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5008","level":"A2","skill":"listening","prompt":"听到 /il pløvɛ/ 后接 /ʒe pʁi/ 时，故事层次是？","options":["先背景后事件","先事件后背景","两个事件并列"],"answer":"先背景后事件","explain":"pleuvait 描写背景，j'ai pris 表示紧接着发生的行动。","source":"语法 · 两种过去时分工"},{"id":"q-read-a2-5008","level":"A2","skill":"reading","prompt":"叙事里未完成过去时主要承担？","options":["描写与铺垫","推进情节","表示将来"],"answer":"描写与铺垫","explain":"未完成过去时负责描写与铺垫，情节推进交给复合过去时。","source":"语法 · 两种过去时分工"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 三种过去时的分工 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-b1b2.html#recit-pc-imp 再核对一次。","src":"grammar-a1a2.html#pc-imparfait","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5015","level":"A2","skill":"grammar","prompt":"« Ils ___ quand nous sommes arrivés. »（dormir，背景）","options":["dormaient","ont dormi","dorment"],"answer":"dormaient","explain":"nous sommes arrivés 是事件，ils 的进行中状态用未完成过去时 dormaient。","source":"语法 · 两种过去时分工"},{"id":"q-gram-a2-5016","level":"A2","skill":"grammar","prompt":"下列哪句用未完成过去时更合适？","options":["Tous les étés, nous allions à la mer.","L'été dernier, nous sommes allés à la mer.","L'été prochain, nous irons à la mer."],"answer":"Tous les étés, nous allions à la mer.","explain":"表示反复出现的过去习惯用未完成过去时；一次性经历用复合过去时；将来用简单将来时。","source":"语法 · 两种过去时分工"},{"ref":"bank:grammar:A2:过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]},{"week":18,"level":"A2","theme":"愈过去时与时间先后表达","days":[{"day":1,"theme":"词汇 · 数字、时间与度量","type":"vocab","steps":[{"type":"vocab","title":"主题词汇域：数字、时间与度量","body":"数字、时间与度量（Les nombres, le temps et les mesures）是这一周要反复见面的主题域。打开 vocab.html#t13，先看词表怎么分组，再把 <span class=\"fr\" data-fr=\"déjà\">déjà</span>（已经）、<span class=\"fr\" data-fr=\"avant de\">avant de</span>（在……之前）、<span class=\"fr\" data-fr=\"après\">après</span>（在……之后）读三遍，然后遮住中文说意思。记不住的词单独建一张「顽固词表」。","src":"vocab.html#t13","hint":"先读后抄，每个词出声读三遍","quiz":[{"id":"q-vocab-a2-5017","level":"A2","skill":"vocab","prompt":"« déjà » 的意思是？","options":["已经","还没有","刚刚"],"answer":"已经","explain":"déjà 表示已经；pas encore 是还没有；venir de 表刚刚。","source":"词汇 · 时间副词"},{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"vocab","title":"搭配与辨析：dès que / un train","body":"<span class=\"fr\" data-fr=\"dès que\">dès que</span>（一……就……）与 <span class=\"fr\" data-fr=\"un train\">un train</span>（火车）是本组最容易混的两个词。为每个词写 2 个搭配（一个名词搭配、一个动词搭配），读出来判断哪个更自然，拿不准的留到第 7 天复盘。","src":"vocab.html#t13","hint":"两个词各写 2 个搭配","quiz":[{"id":"q-vocab-a2-5018","level":"A2","skill":"vocab","prompt":"« dès que » 的意思是？","options":["一……就……","只要","虽然"],"answer":"一……就……","explain":"dès que 表示一……就……；tant que 是只要；bien que 是虽然。","source":"词汇 · 时间连接"},{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"listen","title":"听音辨词：数字、时间与度量","body":"打开 对话页的 d17 篇，先盲听一遍，只做一件事：抓出含本周新词的句子并写下关键词。第二遍再对照法文原文，检查自己漏掉的是词还是联诵。像 <span class=\"fr\" data-fr=\"partir\">partir</span>（出发）这样的词如果没听出来，单独标出来。","src":"dialogue.html#d17","hint":"盲听一遍再对照原文","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"speak","title":"口头造句：6 个新词进短句","body":"用今天抄的 6 个词各说一句，主语在 je / nous / on 之间换着用。参考例句 <span class=\"fr\" data-fr=\"Le train était déjà parti quand nous sommes arrivés.\">Le train était déjà parti quand nous sommes arrivés.</span>（我们到的时候，火车已经开走了。）。录 60 秒，回听时只挑两个问题：冠词有没有丢、动词有没有跟主语配合。","src":"exams.html#oral","hint":"录音 60 秒并回听","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"vocab","title":"日终自测：数字、时间与度量 认词","body":"遮住中文，只看法语说意思：<span class=\"fr\" data-fr=\"déjà\">déjà</span> <span class=\"fr\" data-fr=\"avant de\">avant de</span> <span class=\"fr\" data-fr=\"après\">après</span> <span class=\"fr\" data-fr=\"dès que\">dès que</span> <span class=\"fr\" data-fr=\"un train\">un train</span> <span class=\"fr\" data-fr=\"partir\">partir</span>。说不出来的词立刻回到 vocab.html#t13 重记一遍，并在卡片角上打一个星号，星号词明天先复习。","src":"vocab.html#t13","hint":"先遮中文，再遮法语，两个方向各过一遍","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]}]},{"day":2,"theme":"语法 · 愈过去时","type":"grammar","steps":[{"type":"grammar","title":"语法点：愈过去时","body":"【愈过去时】愈过去时由助动词的未完成过去时（avais / étais）加过去分词构成，表示「过去的过去」，即发生在另一个过去动作之前的事。它常与 avant de、après avoir + 过去分词、dès que 等结构配合，把三层时间关系理清楚。 例句：<span class=\"fr\" data-fr=\"Le train était déjà parti quand nous sommes arrivés.\">Le train était déjà parti quand nous sommes arrivés.</span>（我们到的时候，火车已经开走了。）；<span class=\"fr\" data-fr=\"Après avoir fini ses devoirs, il est sorti.\">Après avoir fini ses devoirs, il est sorti.</span>（做完作业之后，他出去了。）。对照 grammar-a1a2.html#plus-que-parfait 的表格，把规则抄成自己的一句话。","src":"grammar-a1a2.html#plus-que-parfait","hint":"先读规则再看例句","quiz":[{"id":"q-gram-a2-5017","level":"A2","skill":"grammar","prompt":"« Le train ___ déjà parti. »（愈过去时）","options":["était","est","sera"],"answer":"était","explain":"愈过去时是助动词的未完成过去时加过去分词：il était parti。","source":"语法 · 愈过去时"},{"ref":"bank:grammar:A2:愈过去时"}]},{"type":"grammar","title":"规则拆解与常见错误","body":"对着 grammar-a1a2.html#plus-que-parfait 自查三件事：① 触发条件是什么；② 变位或配合落在哪个词尾；③ 有哪些例外要单独记。然后把 <span class=\"fr\" data-fr=\"Le train était déjà parti quand nous sommes arrivés.\">Le train était déjà parti quand nous sommes arrivés.</span>（我们到的时候，火车已经开走了。）拆到词，逐一说明每个成分为什么用这个形式。","src":"grammar-a1a2.html#plus-que-parfait","hint":"合上书默写一遍规则","quiz":[{"id":"q-gram-a2-5018","level":"A2","skill":"grammar","prompt":"愈过去时表示？","options":["发生在另一个过去动作之前","将来要完成","正在进行"],"answer":"发生在另一个过去动作之前","explain":"愈过去时表示「过去的过去」，用于更早发生的事。","source":"语法 · 愈过去时"},{"ref":"bank:grammar:A2:愈过去时"}]},{"type":"read","title":"在短文里找愈过去时","body":"在 grammar-a1a2.html#plus-que-parfait 的例句和章末小测里挑 5 句，圈出所有属于「愈过去时」的成分。读的时候先判断结构再理解意思，不要一开始就在脑子里翻译成中文。","src":"grammar-a1a2.html#plus-que-parfait","hint":"圈出全部相关成分","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"write","title":"限时仿写：8 句","body":"照 <span class=\"fr\" data-fr=\"Le train était déjà parti quand nous sommes arrivés.\">Le train était déjà parti quand nous sommes arrivés.</span>（我们到的时候，火车已经开走了。）的句型仿写 8 句，内容必须是你自己的真实信息。写完用三色笔检查：红色圈主语、蓝色圈动词、绿色圈配合成分，愈过去时 的结构至少出现两次。","src":"exams.html#ecrit","hint":"限时 12 分钟，写完自查","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"语法点巩固：时间连接词","body":"今天再回 grammar-b1b2.html#conn-temps 看一遍 时间连接词，把两个语法点的差别写成一行对照（触发条件 / 形式 / 常见错误各一列）。写不出来就说明还停留在「读得懂」而不是「用得出」。","src":"grammar-b1b2.html#conn-temps","hint":"把两个语法点写成对照表","quiz":[{"ref":"bank:grammar:A2:愈过去时"}]}]},{"day":3,"theme":"精听 · 对话页的 d17 篇","type":"listen","steps":[{"type":"listen","title":"精听（第一遍）：抓主旨","body":"第一遍听的时候不要追求每个词都懂。对话页的 d17 篇 的材料先听三分钟，抓住说话人、场景和态度，其余细节留到第二遍。听之前先用 10 秒预测这段话会出现哪些本周词汇，带着预测去听，抓取效率会明显提高。","src":"dialogue.html#d17","hint":"不暂停、不看文本","quiz":[{"id":"q-list-a2-5009","level":"A2","skill":"listening","prompt":"听到 /il etɛ deʒa paʁti/ 时表示？","options":["他当时已经走了","他现在已经走了","他将已经走了"],"answer":"他当时已经走了","explain":"était 是未完成过去时，构成愈过去时，表示在过去某时之前已经发生。","source":"语法 · 愈过去时"},{"ref":"bank:listening:A2:听力"}],"exam":"exam:listening:A2:车站广播"},{"type":"listen","title":"精听（第二遍）：听写关键句","body":"第二遍逐句暂停，听写 5 句含本周语法或新词的句子，写不出的地方标「?」。然后对照原文，把 ? 处按「词汇 / 联诵 / 语速」三类归档。本周的听力任务是：听一段含「更早发生」的讲述，标出三层时间层次。","src":"dialogue.html#d17","hint":"逐句听写 5 句","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"听力词汇回收","body":"把听写中出现的生词与本周词表对照：<span class=\"fr\" data-fr=\"déjà\">déjà</span>（已经）、<span class=\"fr\" data-fr=\"avant de\">avant de</span>（在……之前）、<span class=\"fr\" data-fr=\"après\">après</span>（在……之后）。反复出现的词优先记，只出现一次又不影响理解的先放过，避免在细节里迷路。","src":"vocab.html#t13","hint":"生词与本周词表对照","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"speak","title":"影子跟读 3 遍","body":"同一段材料做影子跟读（shadowing）：滞后原音半句跟读，重点模仿语调、连读与联诵，不要逐字念。跟完录 45 秒复述，不回看原文，卡住就用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 争取时间。","src":"exams.html#oral","hint":"滞后半句跟读，录 45 秒复述","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"精听（第三遍）：闭合听力","body":"第三遍只听不看，听完用法语说出 3 个关键信息，再写一句「愈过去时 在这段里出现的位置」。仍听不懂的句子重复听 2 次，还不懂就记下来，第 7 天集中解决。","src":"dialogue.html#d17","hint":"只听不看，说出 3 个关键信息","quiz":[{"ref":"bank:listening:A2:听力"}]}]},{"day":4,"theme":"口语 · 愈过去时与时间先后表达","type":"speak","steps":[{"type":"speak","title":"口语任务：本周主题陈述","body":"口语任务：解释一件事的来龙去脉（先发生什么、后来怎样）3 分钟。 开口前先想好「观点—理由—例子」三段，允许说得慢，但不许说到一半换主题。说完立刻自评一句：哪一段最流畅、哪一段最卡，卡住的地方就是下一次的训练重点。","src":"exams.html#oral","hint":"先说满 60 秒不停","quiz":[{"id":"q-speak-a2-5005","level":"A2","skill":"speaking","prompt":"复述来龙去脉时，最早发生的事应该用？","options":["愈过去时","简单将来时","现在时"],"answer":"愈过去时","explain":"三层时间关系中，最早发生的事用愈过去时。","source":"语法 · 愈过去时"},{"ref":"bank:speaking:A2:口语"}]},{"type":"speak","title":"结构与衔接：先列提纲再开口","body":"用 30 秒写 3 个关键词当提纲，再用 <span class=\"fr\" data-fr=\"d'abord\">d'abord</span> / <span class=\"fr\" data-fr=\"ensuite\">ensuite</span> / <span class=\"fr\" data-fr=\"enfin\">enfin</span> 把三段串起来。卡壳时用 <span class=\"fr\" data-fr=\"c'est-à-dire\">c'est-à-dire</span> 或 <span class=\"fr\" data-fr=\"disons que…\">disons que…</span> 争取时间，不要用中文思考再翻译。","src":"exams.html#oral","hint":"三个关键词 + 三段衔接词","quiz":[{"ref":"bank:speaking:A2:口语"}]},{"type":"listen","title":"听范例找差距","body":"听一段同主题范例（对话页的 d17 篇），把自己的录音和范例逐项对比：语速、停顿位置、连接词的使用、愈过去时 的正确形式。只记录 3 个今天就能改的点。","src":"dialogue.html#d17","hint":"只记 3 个可立刻改进的点","quiz":[{"ref":"bank:listening:A2:听力"}]},{"type":"vocab","title":"把新词用进嘴里","body":"把 <span class=\"fr\" data-fr=\"dès que\">dès que</span>（一……就……）、<span class=\"fr\" data-fr=\"un train\">un train</span>（火车）、<span class=\"fr\" data-fr=\"partir\">partir</span>（出发）轮流塞进刚才的答案里，每个词至少用一次。说不顺就说明这个词还没真正归属你，回到 vocab.html#t13 再看一遍例句。","src":"vocab.html#t13","hint":"每个新词至少用一次","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"speak","title":"重录一遍并自评","body":"按前面记录的 3 个问题重录一次，目标是同样的内容用更少的停顿说完。回听时数一数填充词（euh、ben、voilà）出现几次，第 7 天把两次录音放在一起比较。","src":"exams.html#oral","hint":"数一数填充词次数","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":5,"theme":"精读 · 愈过去时与时间先后表达","type":"read","steps":[{"type":"read","title":"精读：本周阅读材料","body":"精读任务：读语法页愈过去时章节与一篇 400 词短篇故事，标出所有愈过去时。 读第一遍只抓主旨，第二遍才处理细节，遇到生词先猜再查。读完先用一句话写出全文主旨，再回头处理细节，避免一开始就陷进生词里。","src":"exams.html#lecture","hint":"第一遍抓主旨，第二遍抓细节","quiz":[{"id":"q-read-a2-5009","level":"A2","skill":"reading","prompt":"« Après avoir fini, il est sorti. » 中 avoir fini 表示？","options":["先发生的动作","同时发生的动作","后发生的动作"],"answer":"先发生的动作","explain":"après 加不定式过去时（avoir 加过去分词）表示主句动作之前先完成的事。","source":"语法 · 时间结构"},{"ref":"bank:reading:A2:阅读"}]},{"type":"read","title":"长句解构：先找主干","body":"把长句按「主干 + 修饰」两栏抄写：左栏只留主谓宾，右栏按顺序列出从句与补语。拆完再合起来读一遍，语序感会明显变好。判断不出从句类型时，先整段框起来，读完上下文再回来标注。","src":"exams.html#lecture","hint":"拆 3 个长句，主干与修饰分栏","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"vocab","title":"阅读词汇：上下文猜词","body":"遇到生词先按词根、词尾和上下文猜一次再核对。本周词表里的 <span class=\"fr\" data-fr=\"déjà\">déjà</span>（已经）、<span class=\"fr\" data-fr=\"avant de\">avant de</span>（在……之前）如果以别的形式出现，把那一整句抄进卡片。","src":"vocab.html#t13","hint":"先猜再查，把整句抄下来","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"grammar","title":"语法在句子里的样子","body":"回到 grammar-a1a2.html#plus-que-parfait，对照文中出现的同类结构，确认书面语和口语的差别。摘抄 3 句可以直接套进写作的句子，标注它们的连接词和语式。","src":"grammar-a1a2.html#plus-que-parfait","hint":"摘 3 句能直接用的句子","quiz":[{"ref":"bank:grammar:A2:愈过去时"}]},{"type":"write","title":"100 词摘要","body":"不照抄原句，用 100 词概括文章并加一句自己的评价。写完统计三个数字：平均句长、连接词数量、「愈过去时」出现次数，看看自己的书面语是不是只会并列短句。","src":"exams.html#ecrit","hint":"改写不照抄，统计三个数字","quiz":[{"ref":"bank:writing:A2:写作"}]}]},{"day":6,"theme":"写作 · 愈过去时与时间先后表达","type":"write","steps":[{"type":"write","title":"写作任务：本周产出","body":"写作任务：改写练习：把 10 个句子改成愈过去时并调整时间连接。 先列提纲再动笔，写完整篇留 5 分钟只做一遍通读检查。动笔前先确认题目要求写几段、用什么语域，避免写到一半推翻结构。","src":"exams.html#ecrit","hint":"先列提纲，再限时成文","quiz":[{"id":"q-writ-a2-5005","level":"A2","skill":"writing","prompt":"「我们到的时候，电影已经开始了」正确写法是？","options":["Quand nous sommes arrivés, le film avait déjà commencé.","Quand nous sommes arrivés, le film a déjà commencé.","Quand nous arrivions, le film commence."],"answer":"Quand nous sommes arrivés, le film avait déjà commencé.","explain":"更早发生的事用愈过去时 avait commencé，到达用复合过去时。","source":"语法 · 愈过去时"},{"ref":"bank:writing:A2:写作"}]},{"type":"write","title":"提纲与逻辑链","body":"动笔前把提纲写成三段式：每段一个论点，每个论点配一个具体例子。检查连接词是否多样，别整段只用 et 和 mais。提纲写完后放一分钟再看一遍，如果一句话就能说清每段的作用，结构就算过关。","src":"exams.html#ecrit","hint":"三段式提纲，每段一个论点","quiz":[{"ref":"bank:writing:A2:写作"}]},{"type":"grammar","title":"写前语法自查清单","body":"打开 grammar-a1a2.html#plus-que-parfait，把本周语法点做成 3 条自查项写在旁边，例如「触发词有没有用对」「变位与配合是否一致」。写完通读只检查这 3 条，其余问题留到第二稿再处理。","src":"grammar-a1a2.html#plus-que-parfait","hint":"三条自查项，只查这三条","quiz":[{"ref":"bank:grammar:A2:愈过去时"}]},{"type":"read","title":"对照范文找可替换表达","body":"读考试页的范文，列出 10 处「我只会用简单说法、范文用了更地道说法」的对照，抄进表达本。重点看范文怎么用「愈过去时」和连接词，对照表按「我的说法 / 范文说法 / 适用场景」三列记录。","src":"exams.html#redaction","hint":"抄 10 组对照表达","quiz":[{"ref":"bank:reading:A2:阅读"}]},{"type":"speak","title":"把写的文章讲出来","body":"脱稿把自己写的文章讲 2 分钟，允许简化但不许背稿。讲不顺的句子说明书面结构还没内化，回到文中改写一次，再讲一遍；同时把 <span class=\"fr\" data-fr=\"déjà\">déjà</span>（已经）用进口语版本。","src":"exams.html#oral","hint":"脱稿讲 2 分钟，不背稿","quiz":[{"ref":"bank:speaking:A2:口语"}]}]},{"day":7,"theme":"复盘 · 愈过去时与时间先后表达","type":"review","steps":[{"type":"review","title":"本周回顾：愈过去时与时间先后表达","body":"这一周围绕「愈过去时与时间先后表达」展开：语法主线是 愈过去时，词汇主线是 数字、时间与度量。先用 3 句话口头复述本周学了什么，再打开日历页第 18 周清单逐条核对里程碑。","src":"calendar.html#wk-18","hint":"先口头复述，再核对里程碑","quiz":[{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"review","title":"语法复盘：愈过去时","body":"从 grammar-a1a2.html#plus-que-parfait 的规则与例句里各抽 3 条：默写规则、翻译例句再对照，最后写下 2 个自己最可能犯的错。凡是默写时卡住的地方，就是下一周要带着继续练的问题。","src":"grammar-a1a2.html#plus-que-parfait","hint":"默写规则与例句，各抽 3 条","quiz":[{"ref":"bank:grammar:A2:愈过去时"}]},{"type":"review","title":"词汇自测：数字、时间与度量","body":"遮住中文看 vocab.html#t13 的 6 个核心词：<span class=\"fr\" data-fr=\"déjà\">déjà</span> <span class=\"fr\" data-fr=\"avant de\">avant de</span> <span class=\"fr\" data-fr=\"après\">après</span> <span class=\"fr\" data-fr=\"dès que\">dès que</span> <span class=\"fr\" data-fr=\"un train\">un train</span> <span class=\"fr\" data-fr=\"partir\">partir</span>。能秒答的划掉，犹豫超过 3 秒的抄进错词本。本周目标是新词认词率不低于 85%。","src":"vocab.html#t13","hint":"遮中文秒答，犹豫即抄错词本","quiz":[{"id":"q-vocab-a2-5019","level":"A2","skill":"vocab","prompt":"« après » 接名词时的形式是？","options":["après 加名词","après de 加名词","après que de 加名词"],"answer":"après 加名词","explain":"après 直接接名词或过去分词，不加 de；avant 也一样。","source":"语法 · 时间结构"},{"id":"q-vocab-a2-5020","level":"A2","skill":"vocab","prompt":"「出发、离开」用法语说是？","options":["partir","rester","rentrer"],"answer":"partir","explain":"partir 是出发、离开；rester 是留下；rentrer 是返回。","source":"词汇 · 出行"},{"ref":"bank:vocab:A1:数字、时间与度量"}]},{"type":"review","title":"综合题（一）：听读理解","body":"先做下面的听读综合题，不查词、不回看材料，限时 5 分钟。做完再回材料定位每道题的证据句，把「没找到证据就选」的题目标出来——那是失分的主要来源。","src":"dialogue.html#d17","hint":"限时 5 分钟，做完回材料找证据","quiz":[{"id":"q-list-a2-5010","level":"A2","skill":"listening","prompt":"听到 /a vwaʁ fini/ 时表示？","options":["先完成之后","正在完成","将要完成"],"answer":"先完成之后","explain":"avoir 加过去分词构成的不定式过去时表示先时性。","source":"语法 · 时间结构"},{"id":"q-read-a2-5010","level":"A2","skill":"reading","prompt":"愈过去时的构成是？","options":["助动词的未完成过去时加过去分词","助动词现在时加过去分词","助动词将来时加过去分词"],"answer":"助动词的未完成过去时加过去分词","explain":"愈过去时用 avais / étais 加过去分词，与复合过去时只差助动词的时态。","source":"语法 · 愈过去时"},{"ref":"bank:listening:A2:听力"}]},{"type":"review","title":"综合题（二）：语法与词汇","body":"这一组题检查 愈过去时 与本周词汇的调用能力。每道题都问自己：错误选项错在哪里？能说出错因才算真的会，说不出来就回到 grammar-a1a2.html#plus-que-parfait 再核对一次。","src":"grammar-b1b2.html#conn-temps","hint":"每题都说出错项错在哪","quiz":[{"id":"q-gram-a2-5019","level":"A2","skill":"grammar","prompt":"« Elle ___ avant notre arrivée. »（partir，愈过去时）","options":["était partie","est partie","sera partie"],"answer":"était partie","explain":"partir 用 être，愈过去时写作 elle était partie，分词与主语配合成 partie。","source":"语法 · 愈过去时"},{"id":"q-gram-a2-5020","level":"A2","skill":"grammar","prompt":"「先……再……」的表达是？","options":["d'abord… puis…","déjà… encore…","ici… là…"],"answer":"d'abord… puis…","explain":"d'abord 与 puis 表示先与再；déjà 只表示已经。","source":"语法 · 时间结构"},{"ref":"bank:grammar:A2:愈过去时"}]},{"type":"review","title":"输出任务与自评表","body":"完成一段 90 秒口述或 120 词短文，内容必须同时用上本周的 2 个词和 1 个语法结构。按「任务完成 / 连贯 / 词汇 / 语法 / 拼写」五项各打 1–5 分，低于 3 分的写进下周补漏清单。","src":"exams.html#oral","hint":"五项各打 1–5 分","quiz":[{"ref":"bank:writing:A2:写作"}]}]}]}];
